window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["35368398"]={"book":{"id":35368398,"title":"费曼学习法","author":"尹红心 李伟 ","translator":"","publisher":"江苏凤凰文艺出版社","pubdate":"2021","isbn":"9787559454911","tags":["心理学"],"memCount":null},"np":1,"pb":[13],"idx":[{"i":20097,"t":"费曼学习法：用输出倒逼输入","l":"TF2-1","c":"李珍琪","g":1,"p":1},{"i":19789,"t":"费曼学习法","l":"TF1-1","c":"赫游之","g":1,"p":1},{"i":18106,"t":"让知识学为己用，精进实践","l":"TF2-1","c":"书书何","g":1,"p":1},{"i":17954,"t":"知识内化的5个步骤","l":"TF1-1","c":"火火Esther","g":1,"p":1},{"i":17621,"t":"如何实施费曼学习法","l":"TF1-1","c":"璞玉浑金","g":1,"p":1},{"i":16597,"t":"如何快速理解书中的知识","l":"TF2-2","c":"金老师","g":1,"p":1},{"i":16119,"t":"如何抵抗遗忘？","l":"TF2-1","c":"宁静@微光","g":1,"p":1},{"i":15930,"t":"如何找到真正的兴趣","l":"TF1-1","c":"Chunling","g":1,"p":1},{"i":15853,"t":"如何实施费曼学习法","l":"TF1-1","c":"宁静@微光","g":1,"p":1},{"i":14462,"t":"用费曼学习法复述知识","l":"TF2-3","c":"支帆","g":1,"p":1},{"i":13436,"t":"费曼学习法步骤","l":"TF1-2","c":"Joanna Liu","g":1,"p":1},{"i":12239,"t":"以教代学，通过简洁有深度的输","l":"TF1-2","c":"abbylzw","g":1,"p":1},{"i":11411,"t":"三步把学到的知识“可视化”","l":"TF1-1","c":"李婧初","g":1,"p":1}],"ms":[{"id":20097,"topic":"费曼学习法：用输出倒逼输入","learn_goal":"","remark":"你是不是也有这样的经历？读了一本书，划线划得密密麻麻，过一个月却想不起讲了什么；听了一门课，笔记记了厚厚一本，真要用的时候却说不出个所以然；学了一个新技能，当时觉得“我懂了”，动手一做就露怯。学的时候很努力，用的时候很无力。\n\n告别低效的输入式学习，五步法带你从“听过、看过、学过”走向“讲得出、用得上”。\n✅ 掌握“确立目标、理解对象、以教代学、回顾反思、简化吸收”五步完整流程，让每次学习都能真正扎根。\n✅ 学会用“输出倒逼输入”精准定位理解盲区，在卡住的地方重新学，告别“以为懂了”的错觉。\n✅ 懂得将知识简化成自己的语言和工具，随时调用，再也不用“书到用时方恨少”。\n【拆书介绍】：\n今天为大家带来的是《费曼学习法》这本书中关于“以教代学”的核心片段。教大家如何用输出倒逼输入，告别学了就忘、用不出来的低效学习，把知识真正变成自己的。\n","level":"TF2-1","duration":29,"status":10,"type":0,"chaishujia":{"username":"李珍琪","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位小伙伴们好，我叫李珍琪，我用三个标签做一下自我介绍。第一个标签是“培训”，我的职业是从事培训相关工作。第二个标签“早起”，在工作日我坚持5:30 起床，利用早起的这段时间学习。第三个标签是“拼豆”，这是我最近迷上的一项手工。\u003c/p>\u003cp>\u003cstrong>【书籍介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F（特征）：\u003c/strong>今天拆解的片段出自书籍《费曼学习法》，由尹红心、李伟撰写。这本书系统阐述了诺贝尔物理学奖得主理查德·费曼的核心学习理念——以教代学，用输出倒逼输入，围绕这一理念展开了一套从目标确立到知识内化的完整学习流程。\u003c/p>\u003cp>\u003cstrong>A（优势）：\u003c/strong>市面上很多学习法侧重于“怎么输入”，比如如何速读、如何记笔记；而这本书独辟蹊径，从“怎么输出”的角度重构学习过程，强调“如果你不能向其他人简单地解释一件事，那么你就还没有真正弄懂它”。书中提供了可操作的五个步骤，让抽象的学习变得有章可循。\u003c/p>\u003cp>\u003cstrong>B1（这本书的收益）：\u003c/strong>通过阅读这本书，大家可以掌握一套以输出为导向的学习方法，大幅提升知识留存率，让学过的知识真正变成自己的东西，而不是学了就忘。\u003c/p>\u003cp>\u003cstrong>B2（本次拆解片段的收益）：\u003c/strong>今天我将带大家拆解书中的核心内容，也就是费曼学习法五步法，帮助大家当场掌握这套方法，回去就能用在读书、学技能、准备考试等各种学习场景中。\u003c/p>","ratings_count":1,"texts":[{"id":24546,"quote":"\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>那具体是怎么做的呢？请大家花1-2分钟时间来阅读一下这个片段。阅读完的小伙伴请示意我一下。\u003c/p>\u003cp>\u003cstrong>【R】\u003c/strong>\u003c/p>\u003cp>它的核心是——当你准备学习一门新知识时，必须站在传授者的立场，假设自己要向别人讲解这门知识。那么你一定要用最简洁、清晰和易于理解的语言表达出来，才能让行外的人也能听懂。费曼说:“最好是几岁的小孩也能明白你在说什么。”为此，他制定了一个简单易行的流程：\u003c/p>\u003cp>第一，确立你要学习的目标。找到和列出自己想要了解的知识，可以是一本书，也可以是一门技术，甚至是你能想象到的任意领域和事物。\u003c/p>\u003cp>第二，理解你要学习的对象。针对这个目标，准备好和筛选相关的资料，选择可靠和多个角度的信息来源，把这些内容系统化地归纳整理出来。\u003c/p>\u003cp>第三，以教代学，用输出代替输入。模拟一个传授的场景，用自己的语言把这些知识讲给别人，用以检查自己是否已经掌握了这些知识。\u003c/p>\u003cp>第四，进行回顾和反思。对其中遇到阻碍、模糊不清和有疑义的知识重新学习、回顾和反思。如有必要，可以重整旗鼓，进行再一次输出。\u003c/p>\u003cp>第五，实现知识的简化和吸收。最后，通过针对性的简化和整合，实现这些知识的内化和有效的应用。\u003c/p>\u003cp>通过这五个步骤，我们很容易便能获得最高的内容留存率，加强学习的效果，让自己顺利地达到学习和输出知识的目的。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>我们来看下这个片段主要讲了什么。这个片段讲的是费曼学习法的核心思想和五个操作步骤。\u003c/p>\u003cp>那费曼学习法到底是什么呢？简单说，就是通过“教别人”来倒逼自己真正学会。它的底层逻辑是：如果你不能把一件事用简单的话讲清楚，说明你还没有真正理解它。\u003c/p>\u003cp>所以费曼学习法不是“学完再去教”，而是“为了教而学”，把输出作为学习的起点和检验标准，形成一个“目标—&gt;理解—&gt;输出—&gt;反思—&gt;简化”的完整闭环。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点：不这么样的坏处】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;一般人的做法&gt;\u003c/strong>\u003c/p>\u003cp>很多人学习的时候是怎么做的呢？最常见的方式就是“输入式学习”，看书、听课、记笔记，把大量信息往脑子里塞。一本书从头读到尾，划了重点、做了摘抄，就觉得“我学完了”；听完一门课，笔记记了厚厚一本，就觉得“我学会了”。表面上看，大家都在“学习”，但看完不等于你理解了，更不等于你掌握了。\u003c/p>\u003cp>\u003cstrong>&lt;一般做法的坏处&gt;\u003c/strong>\u003c/p>\u003cp>这种“输入式的学习”有什么影响呢？\u003c/p>\u003cp>第一，知识留存率低。根据学习金字塔理论，被动输入的学习方式，例如听讲、阅读等，知识留存率不到30%；而主动输出的留存率可达90%，例如教授他人。很多人看完一本书、学完一门课，过一个月能记住的不到20%。大量时间和精力投入了，真正留下的东西却很少。\u003c/p>\u003cp>第二，学和用脱节。很多人学了很多知识，但需要用的时候却说不清楚、更不知道怎么用。因为输入式学习只完成了“知道”这一步，没有经历“理解—&gt;输出—&gt;内化”的转化过程。知识停留在别人的文字/语言里，没有变成你自己的东西。\u003c/p>\u003cp>\u003cstrong>&lt;反面案例&gt;\u003c/strong>\u003c/p>\u003cp>我是做企业培训的，日常运营培训项目时，经常需要把课程核心知识点整理成知识卡片，方便学员复习和传播。为了提升这方面的能力，我特意报名学习了一门AI+知识卡片的线上课程。听课的时候感觉都懂了，提示词、排版原则、配色技巧、信息分层，每一节课都认真跟下来了。但学完之后，自己做出来的卡片效果始终不太理想：要么信息层级混乱，一张卡片上堆了太多内容，学员看了抓不住重点；要么排版怎么调都不对劲，花了不少时间反复修改提示词，AI输出质量还是不稳定。课程学完了，好像该知道的都知道，但一到动手输出就有很多问题。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong> \u003c/p>\u003cp>那费曼学习法到底怎么做呢？有五个步骤。\u003c/p>\u003cp>第一步：确立学习目标。明确你要学什么，可以是一本书、一门技术、一个概念。把目标写下来，越具体越好。\u003c/p>\u003cp>第二步：理解学习对象。围绕目标搜集资料，从多个角度理解知识点，把内容系统化地整理出来。\u003c/p>\u003cp>第三步：以教代学。模拟一个教学场景，用自己最简洁、清晰的语言把知识讲给别人听，可以是真人，也可以是假想的听众，目标是让一个完全不懂的人也能听懂。\u003c/p>\u003cp>第四步：回顾反思。在讲解过程中遇到卡壳、讲不清楚的地方，就是你没真正理解的地方。回去重新学习这部分，直到能讲明白为止。\u003c/p>\u003cp>第五步：简化吸收。把学到的知识进一步简化和整合，用最精炼的方式表达出来，让它真正变成你自己的东西。\u003c/p>\u003cp>\u003cstrong>&lt;正面案例&gt;\u003c/strong>\u003c/p>\u003cp>如果我当时学完AI+知识卡片课程后，就用费曼学习法来巩固，会怎么做呢？\u003c/p>\u003cp>第一步确立目标：我要真正掌握用AI制作知识卡片的方法，能够稳定输出高质量的卡片，而不仅仅是“听过课、记过笔记”。\u003c/p>\u003cp>第二步理解对象：重新梳理课程内容，把提示词撰写、排版原则、配色技巧、信息分层这些知识点系统整理一遍，不仅整理“怎么做”，还追问“为什么这么做”。\u003c/p>\u003cp>第三步以教代学：我假想自己要在团队内部做一次转训，把用AI做知识卡片的方法教给团队伙伴。在准备“怎么教别人”的过程中，我自己先拿一个主题试做了一张，卡住了。在提示词里描述排版样式，具体怎么描述、描述到什么程度，我是有点模糊的。我翻来覆去试了好几轮，出来的排版不是信息挤成一团，就是视觉流向完全不对。我虽然能勉强调到“看得过去”的程度，但到底怎么把排版要求清晰地写进提示词里，自己也糊里糊涂，更别说提炼出一套方法教给别人了。\u003c/p>\u003cp>第四步回顾反思：被自己问住之后，我去看了大量优秀知识卡片的排版结构，反复对比分析，发现核心逻辑是：排版不是在提示词里画图，而是用文字定义结构。我把这个逻辑拆成了两句能写进提示词的话：“左右分栏布局，左侧1/3放核心观点，右侧2/3放支撑论据和案例，从上到下按优先级排列。”然后把这句话反复调整，直到AI能稳定输出符合预期的排版。\u003c/p>\u003cp>第五步简化吸收：我把这套逻辑进一步简化成一份可直接粘贴进AI的提示词排版模板，团队伙伴拿到就能直接用，不需要自己从头摸索描述方式。\u003c/p>\u003cp>这样一来，原本“学了但做不好”的AI知识卡片，通过“为了教别人”这个动作，真正被我理解透了。不仅我自己摸索出了可复用的提示词排版方法，后续再出卡片时效率和质量都明显提升了。\u003c/p>\u003cp>其实后面我确实也是这么做的，我在团队内部进行了分享，不仅教会了团队小伙伴怎么做AI知识卡片，我自己的水平也在教的过程中更精进了。\u003c/p>\u003cp>\u003cstrong>【where】--不适用的场景\u003c/strong>\u003c/p>\u003cp>关于费曼学习法的适用边界，有以下两点提醒。\u003c/p>\u003cp>第一，费曼学习法适用于绝大多数需要深度理解和掌握知识的学习场景，读书、学技能、备考、准备演讲或培训等。只要是“学东西”的场景，都可以用。尤其适合那些“学了但用不出来”的知识。如果你发现学完一门课、一本书，却说不出个所以然，那就是费曼学习法最能发挥作用的时候。\u003c/p>\u003cp>第二，费曼学习法不适用于纯动作技能、感性体验等场景；在完全零基础或只需泛读了解时，也不宜强行套用完整五步，否则效率低下。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;显像提问&gt;\u003c/strong>\u003c/p>\u003cp>以上就是关于费曼学习法的介绍，接下来请大家回想一下，你最近有没有这样的经历：读了一本书、听了一门课、学了一个新技能，当时觉得自己“学会了”、“记住了”，但过了一段时间，别人问你这个东西讲了什么，你却说不清楚，或者要用的时候完全想不起来。\u003c/p>\u003cp>可能你只是从头到尾读完了一本书，划了重点，但没有尝试输出；也可能你听课记了详细的笔记，但从来没有用自己的话复述过；又或者你学的时候感觉懂了，但一讲就卡壳，才发现自己根本没理解透。\u003c/p>\u003cp>当时你是怎么学的？是哪个环节没有做到位，导致学了等于没学？请小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者月巧：\u003c/strong>好的，我先分享一下。我觉得对于这点太有发言权了。因为就是之前看过的书，然后等我再翻出来想做拆页的时候，我发现这本书根本想不起来读了些啥。然后当时就觉得挺好的。当我做拆页的时候，好多内容根本都想不起来，只能重新再读一遍。对，我觉得就是没有想着要输出，然后只是看完，就停留于看完画线，我就好像学会了。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>所以你就是把一本书从头读到尾对吧？\u003c/p>\u003cp>\u003cstrong>分享者月巧：\u003c/strong>对，然后到最后也还写一篇文章，然后写了一下收获。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>所以就是在读这本书的时候，可能没有明确你为什么要读这本书，对吧？然后读完之后，你只是写了一篇分享感想的文章，但是没有去做一些核心的能够解决实际问题的一些输出。\u003c/p>\u003cp>\u003cstrong>分享者月巧：\u003c/strong>当时就觉得这个书名也许能解决当下的问题，然后觉得好像有用。但是发现首先确实目标也不明确，其次就是读的就只是停留于，很简单的写了。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>明白，谢谢月巧的分享。其实月巧很真诚。我们大部分小伙伴可能其实在阅读的时候也是这样子的一些情况，就是可能没有想清楚为什么要去读，然后直接就读了，读完就是画了很多线，可能也没有做一些输出。还有没有其他小伙伴要分享一下？\u003c/p>\u003cp>\u003cstrong>分享者老贾：\u003c/strong>我来说几句，好吗？我觉得这个太正常了。我们太多遇到过这种情景，就是我们看过很多书，或者是看过一个包括视频也好，电影也好，或者其他也好，他可能有几个点，可能对你有一点印象。但是如果你要想完整的想把它或者相对来说比较完整的能够给人家讲出来，这个确实难度就比较大了。我今天上午在做这个培训的时候，因为我现在在云南一个企业，然后在做培训的时候，我就说过这个可能大家都知道这么几点内容。一个叫做一听，叫什么一听就会，一做就废了。就是这个实际上在我们生活工作里边非常的多，对吧？好像一听就明白了，但是让你去做，一方面，这儿也不对，那儿也不对，是吧？这就很明显的。还有叫做我们说句话就是叫好记性不如烂笔头。过去说我们听懂了，我们就有一个叫艾宾浩斯遗忘曲线是吧？2个小时以后或者几个小时以后，你脑子里可能剩不下什么东西。我觉得它是一个规律，而不是对某个人来说，所有人其实都是符合这些的。那我们怎么去克服这个问题呢？就是要方法了是吧？我们可以克服，一个是我们在听的过程中要把它记下来。第二就是我们听完了以后，我们要动手，然后把它练出来是吧？这样的话对加强我们的一个记忆就特别有帮助。尤其是刚才我们看到您介绍这个费曼学习法，那不光是我要把它记下来，而且我还要讲给别人听，让别人能够听得懂，这个对我们的要求就更高一级了。我觉得费曼这个学习方法真的是很棒的。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，谢谢老贾的分享。帮我们总结了大家其实都存在的共性问题，非常精妙，一听就会，一做就废，确实是大多数人都存在的问题。然后确实是在听看的过程中做记录是一个点。还有就是我们要动手去做，然后还有就是费曼强调的，我们要去有一些输出，要去输出给别人，让别人能听懂。\u003c/p>\u003cp>\u003cstrong>&lt;A1+&gt;\u003c/strong>\u003c/p>\u003cp>好，刚才大家都分享了自己学了但没真正掌握的经历。现在请大家回到刚才你分享的那个场景里：假如当时你就掌握了费曼学习法五步法，你会怎么做？具体每一步可以怎么用？请大家先思考下，我们稍后邀请小伙伴来分享下。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者月巧：\u003c/strong>我正好在这两天准备过级，非常有感触。就像我这次准备过级一样，我觉得确立了目标了，我就是要讲给大家听。学习对象就是咱们拆书帮的会员是吧？我要用RIA的方式，然后用R变签、I变签、A变签要教给大家。我就觉得在看书的时候，一下子就可以把这本书读薄了。有些东西在写的时候，在写预备表，在写逐字稿的时候，当时觉得有些东西感觉好像明白了。又在不断的回看，就是这本书真的有不断的翻，不断地翻。我又去反思，然后再去整理稿件，然后再写的时候再去跟老师提出问题，然后再针对我们的拆解的目标技能点。这个东西我今天、昨天也是跟师傅不断的对，然后他说这个东西你只要去做的时候，你才可以对技能点不断的有理解的清楚。就是这样。当时看一下感觉好像懂了，然后再结合书本，然后我结合技能点去拆出来的时候就发现还是有好东西没有理解到位。这些我觉得就是不断的再去回顾反思，然后在想今天教给大家的时候要去怎么搞。然后我就这本书真的读到位了。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>谢谢月巧的分享。说的很好，分享的很好啊。说到我们拆书也是一种费曼学习法，确实就是这样子的。我在整理我的这个拆书资料的过程中，我也发现其实我们拆书帮的这种拆书的学习方式，其实就是一种费曼学习法。还有其他伙伴要分享一下吗？时间原因我们再请一位伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>分享者Susan ：\u003c/strong>好的，我分享一下就是通过费曼学习法，我本来最近我是想抓紧学英文，然后过水平考试。我要准备什么资料呢？就是那些英语APP平台、书籍资料等等。过一段时间我还要去报个班，报一个英语的冲刺班。\u003c/p>\u003cp>然后我要教给谁？我现在就是教老外学中文，我不收他们的费用，我就安心的教教他们学中文。在这个过程当中，我就把我的英文练习进去了。然后通过他们的反馈，我就知道自己的英文是否进步。我比如说我最近一个月学的新单词有没有用进去，我的短语有没有用进去，他们能不能理解，能表达清楚，他们理解了，这些我都能够得到反馈。\u003c/p>\u003cp>然后最终我就是想我的英文多进步，多进步了以后，对自己以后的职业工作也好，还是人生也好，都有一个很大的帮助。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>好的，谢谢Susan的分享。就非常具体的一个后续关于学英文的一个规划，用费曼学习法去做了一个规划。这里补充说明一下，像Susan她是在学英文，但是她是教老外学中文，她是在教中文的过程中要跟大家去沟通英文。我们第三步的以教代学，其实是想说你要去教别人你正在学的这个东西，其实你要去教他英文，但是Susan她的这个过程虽然是教中文，但是确实也是去在实践她的一个英文水平，也能够帮她练习。但是这是跟费曼学习法有一点点区别的地方。好的，老贾老师，因为时间原因，我们可以过后再来讨论和交流一下，可以吗？\u003c/p>\u003cp>最后快速回顾一下今天的内容。\u003c/p>\u003cp>我们拆解了费曼学习法五步法，分别是确立目标、理解对象、以教代学、回顾反思、简化吸收。核心就一句话：教是最好的学。如果你不能把一件事简单讲清楚，就说明你还没有真正弄懂它\u003c/p>\u003cp>我的分享完毕，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1788429802000,"updated_at":1788429818000,"ria":true},{"id":19789,"topic":"费曼学习法","learn_goal":"","remark":"/","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"赫游之","city":""},"club":{"name":"沈阳海棠分舵","city":"沈阳"},"prologue":"\u003cp>大家好是赫游之，来自新疆，是一名智能制造项目经理，也是一名持续践行RIA学习法的初学者。今天，我为大家带来的拆书分享来自《费曼学习法》这本书。希望通过这次分享，大家都能学会费曼学习法，并能立刻制定一个应用计划。\u003cbr>拆书帮是基于RIA学习法的公益组织，通过现场拆书、拆书课等形式，聚集爱书之人，共同提升学习力和解决问题的能力。\u003cbr>使命：致力于培养拆书家，释放拆书家能量，相互陪伴，助人达己\u003cbr>愿景：帮助拆书家升级学习力及促进他人学习的能力，影响身边人，让世界变得更好一点。\u003cbr>拆书帮最核心的学习方法就是RIA学习法，首先是阅读原文，然后通过自己的语言把片段重新讲解，最后内化为自己的知识，并应用执行。\u003c/p>","ratings_count":1,"texts":[{"id":24217,"quote":"\u003cp>众所周知的“费曼学习法”，它的核心是——当你准备学习一门新知识时，必须站在传授者的立场，假设自己要向别人讲解这门知识。那么你一定要用最简洁、清晰和易于理解的语言表达出来，才能让行外的人也能听懂。费曼说：“最好是几岁的小孩也能明白你在说什么。”为此，\u003cbr>他制定了一个简单易行的流程： \u003cbr>\u003cstrong>第一，确立你要学习的目标。\u003c/strong>找到和列出自己想要了解的知识，可以是一本书，也可以是一门技术，甚至是你能想象到的任意领域和事物。\u003cbr>\u003cstrong>第二，理解你要学的对象。\u003c/strong>针对这个目标，准备好和筛选相关的资料，选择可靠和多个角度的信息来源，把这些内容系统化地归纳整理出来。\u003cbr>\u003cstrong>第三，以教代学，用输出代替输入。\u003c/strong>模拟一个传授的场景，用自己的语言把这些知识讲给别人，用以检查自己是否已经掌握了这些知识。 \u003cbr>\u003cstrong>第四，进行回顾和反思。\u003c/strong>对其中遇到阻碍、糊不清和有疑义的知识重新学习、回顾和反思。如有必要，可以重整旗鼓，进行再一次输出。 \u003cbr>\u003cstrong>第五，实现知识的简化和吸收\u003c/strong>。最后，通过针对性的简化和整合，实现这些知识的内化和有效的应用。 \u003cbr>通过这五个步骤，我们很容易便能获得最高的内容留存率，加强学习的效果。\u003c/p>","explains":"\u003cp>what\u003cbr>这个片段主要讲述了费曼学习法的方法步骤，\u003cbr>why\u003cbr>通过费曼学习法可以快速掌握和理解知识，提升学习效果，快速掌握一门技能或者一本书。\u003cbr>how\u003cbr>费曼学习法主要通过五个步骤执行，最核心的方法就是用自己的语言教会他人知识的方式来倒逼自己理解知识。\u003cbr>1. 明确学习目标：首先就是要明确我们要学习什么，比如你是学生要学习高数，或者你是项目经理要考取项目管理师资格证，可以是任何你想要学习的知识或技能，只有明确了学习目标才能开展下一步学习计划。\u003cbr>2. 理解学习对象：针对学习对象，要收集并学习相关的知识，可以收集相关的书、课程、试题等进行学习和理解。\u003cbr>3. 输出倒逼输入：可以把自己当做老师，向他人用自己的语言描述知识，并且能够让他人能理解这些知识，可以准备PPT、思维导图等方式向他人讲解知识，如果别人也能听懂那么也证明自己是掌握了。\u003cbr>4. 进行复盘反思：在向他人讲解知识时过程中，如果遇到卡点或疑问，可以记录下来并反复学习理解知识，然后再次向他人讲解，反复循环直到完全掌握这门知识。\u003cbr>5. 知识整理内化：最后要把过程中相关文档资料做归集，通过建立思维导图、编写方案等多种方式形成自己的专属知识体系。\u003cbr>where\u003cbr>费曼学习法使用场景非常广泛，可以适用于我们学校学习数学、物理等知识，也可以用于职场学习项目管理、人际关系处理等技能，也可以用于掌握一本书。\u003cbr> \u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>故事：让我想起了高中时期，为啥学习那么好，因为总是同桌、同学来问我数学问题，我给他们讲解，自然而然运用了费曼学习法，用自己的语言教会别人，在这个过程中首先明确问题本身，然后自己先去快速思考做题，然后在给同桌讲解，加深理解，遇到卡壳的问下别人如何处理的，然后完善自己的答案，最后在课堂上给全班同学分享。\u003c/p>\u003cp>反思：在今后工作当中，要继续应用费曼学习法，将项目实施的方法教会项目团队员工，一方面加深项目管理的理解，另一方面也能提升团队能力更好交付。\u003c/p>\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>目标：通过一周的时间费曼学习法完成番茄工作法的学习，并做为下次拆书的内容。\u003c/p>\u003cp>行动：1. 首先明确目标，学习番茄工作法\u003c/p>\u003cp> 2. 理解学习对象，收集番茄工作法的相关知识，花上2天时间读完樊登老师的《番茄工作法》，在收集阅读微信公众号上的相关文章3篇。\u003c/p>\u003cp> 3. 整理学习番茄工作法并形成思维导图和PPT，找个同事向他讲解番茄工作法的原理\u003c/p>\u003cp> 4. 记录讲解过程中的卡点，反复学习5.完善番茄工作法的思维导图和PPT，做到能复用。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1774702632000,"updated_at":1777377737000,"ria":true},{"id":18106,"topic":"让知识学为己用，精进实践","learn_goal":"","remark":"拆解书籍二：《费曼学习法》 时长：20-25分钟\n\n\n\n\n\n\n每一个终身的学习者，都需要实践费曼学习法才可以突破只能感动自己的低质量的努力。把书本上的知识纳入自己大脑中的知识结构，学习者才可以成为更好的自己！\n\n拆书家【书书何】带你拆解《费曼学习法》，通过五个步骤，让学习者从高效科学的学习方法中获得实践上的提升。\n","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"书书何","city":"南京"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>大家下午好，今天和大家一起拆书，进行2-1的定级。开始之前，我来做个分组，接下来我来介绍我今天给大家分享的这本书\u003c/p>\u003ch1>\u003cstrong>图书介绍\u003c/strong>\u003c/h1>\u003cp>\u003cstrong>f\u003c/strong>：本书主要讲述了诺贝尔奖获得者天才物理学家费曼创造的学习方法和技巧，这种方法通过以教促学的主动学习，用输出倒逼输入，让学习留存率高达百分之九十，是公认的高效学习方法，我们能在很多知名人士的演讲和书籍中看到费曼学习法的影子，全球多所顶尖大学和跨国公司的培训中都在使用费曼学习法，这个方法非常适合每一个积极向上的终生学习者实践。\u003c/p>\u003cp>\u003cstrong>a\u003c/strong>：国内外介绍费曼学习的书有很多本，不同的作者写作针对不同应用场景。综合对比来但这个版本的这部分拆页我感觉最精炼，所以选择了这个版本和大家一起分享。\u003c/p>\u003cp>\u003cstrong>b\u003c/strong>：无论是在学生时代学科知识的学习，还是在进入职场以后，学习者在个人成长方面的终身学习，想要在学习上取得成效 不是靠努力就有用的，学习者要在掌握科学高方法的前提下去尽力 。所以我们要通过今天阅读，掌握费曼学习法，明白如何把书本上的信息，变成自己的知识，通过为我所用，学以致用，促进个人成长，甚至影响更多人实现社会价值，\u003c/p>\u003cp>接下来请大家用三分钟阅读一下拆页\u003c/p>\u003ch2>\u003c/h2>","ratings_count":2,"texts":[{"id":22360,"quote":"\u003cp>2-1拆书原文片段 费曼学习法\u003c/p>\u003cp>物理学家费曼的一生有着足以铭刻史册的学术成就，他也因自己独特的教学方式广为人知，深受推崇。在大学教授物理学时，他总是能够深入浅出地将复杂的专业理论讲得通俗易懂，无论多么抽象、晦涩的概念，都能用非常生活化的例子表达出来，风趣幽默，一点也不枯燥。学生喜欢上他的课。后来，越来越多的人便采用他的这种方法学习，最终形成了人们众所周知的“费曼学习法”。\u003c/p>\u003cp>它的核心是——当你准备学习一门新知识时，必须站在传授者的立场，假设自己要向别人讲解这门知识。那么你一定要用最简洁、清晰和易于理解的语言表达出来，才能让行外的人也能听懂。费曼说:“最好是几岁的小孩也能明白你在说什么。”为此，他制定了一个简单易行的流程:\u003c/p>\u003cp>第一，确立你要学习的目标。找到和列出自己想要了解的知识，可以是一本书，也可以是一门技术，甚至是你能想象到的任意领域和事物。\u003c/p>\u003cp>第二，理解你要学习的对象。针对这个目标，准备好和筛选相关的资料，选择可靠和多个角度的信息来源，把这些内容系统化地归纳整理出来。\u003c/p>\u003cp>第三，以教代学，用输出代替输入。模拟一个传授的场景，用自己的语言把这些知识讲给别人，用以检查自己是否已经掌握了这些知识。\u003c/p>\u003cp>第四，进行回顾和反思。对其中遇到阻碍、模糊不清和有疑义的知识重新学习、回顾和反思。如有必要，可以重整旗鼓，进行再一次输出。\u003c/p>\u003cp>第五，实现知识的简化和吸收。最后，通过针对性的简化和整合，实现这些知识的内化和有效的应用。\u003c/p>\u003cp>通过这五个步骤，我们很容易便能获得最高的内容留存率，加强学习的效果，让自己顺利地达到学习和输出知识的目的。在本书中，我们围绕费曼的学习思想和他的教学经验，对这五个步骤的要点、原则和应用的场景进行了全方位的解读。\u003c/p>\u003cp>我在书中重点强调的是，学习和应用是互为一体的，无法对外输出的学习就不能称为学习。这是我对自己的学生、读者和年轻人的希望之一，阅读本书，学习费曼的思路，是要让我们拥有出色的应用知识的能力，能够输出知识，创造知识,并用知识改造世界。\u003c/p>","explains":"\u003cp>这个片段很简洁，我观察到大家都阅读结束来，这段拆页讲述费曼学习法的五个步骤\u003c/p>\u003ch2>\u003cstrong>What\u003c/strong>\u003c/h2>\u003cp>每个人的人生路程都得面对学习，想要从被动服从式学习转变到主动学习，从低质量的努力转变到高质量的尽力，我们得采用科学高效的方法，费曼学习法的五个步骤就可以让我们一步步循序渐进的把我们逐渐把知识内化。\u003c/p>\u003ch2>\u003cstrong>why\u003c/strong>\u003c/h2>\u003cp>如果我们仅仅只听一堂课，学习者没有经过思考盲目的照单全收，其实知识留存率只有百分之五，而通过阅读的知识留存率也仅仅只有百分之十，大部分的知识还停留在书本上或者课件上，无法内化进自己的知识框架，更别谈去作用于实践，学习效率太低。\u003c/p>\u003cp>盲目的碎片化学习只积累数量做不到成体系，只能学到一堆空洞的结论而非扎实的逻辑，，只能肤浅的看到表面的现实，不明白底层逻辑。 看待问题简单化，片面化，思维狭隘，视野局限， 没有长远性。 无法进行独立有深度的思考。\u003c/p>\u003ch2>\u003cstrong>how\u003c/strong>\u003c/h2>\u003cp>因此，学习者应该采用费曼学习法的五个步骤来提高学习效率。，\u003c/p>\u003cp>一个是明确目标，要确定学习的对象，这是主动学习的第一步，带着开放性思维和批判性思维去重新确立主动积极的学习意义。有主动学习的思维才能聚焦于目标并且投入在其中。\u003c/p>\u003cp>第二步是理解，学习中把基本的知识点理清楚，把零碎的知识点有逻辑的搭建层级结构，和已经有的知识和经验进行关联，构建出自己独有的知识体系，这也是开始内化的开始。\u003c/p>\u003cp>理解的过程是筛选和提取精华，是带着问题去学习的，主动去寻求答案，找出和实际需要匹配的知识，进行归纳总结，和相似概念进行对比，类比，\u003c/p>\u003cp>第三步：以教代学用输出倒逼输入，积极主动的去提取之前学到的知识，还会关联相关的所有信息，并且用自己的语言来概括这些信息的同时其实强化了自身对知识的理解。教学会暴露学习者在知识层面的缺陷，自己没有真正的理解清晰，把零碎的知识整理成有逻辑联系的架构，清晰明白每个步骤的作用和联系，每个概念自身的多层逻辑架构，是无法跟他人解释清楚的。，这个输出的过程可能不仅仅是一次，是反复多次。\u003c/p>\u003cp>第四步 并不是输出结束，至关重要的一步是要通过反馈来复盘，每一个反馈都可能是思维的碰撞，是一个可以打开全新窗口的突破。我们解决问题的过程就是在获得智慧，实现成长。知识在应用中才会意识到我们自己到底有没有真正的理解所学的知识。\u003c/p>\u003cp>第五步 最经过了以上四步，最后就把知识进行自己的归纳和总结，把知识条理化，系统化。 用自己的方式进行简化归纳总结成简洁的核心逻辑， 比如：所有的概念的分类，按照核心概念和逻辑层级，梳理清晰 进行要点提炼。这个过程也就把这些知识整合到自己的知识框架里面， 产生自己独有知识系统。转化为长时记忆。 这一步也是高阶学习者的关键，形成自己的原创观点成为专家。 \u003c/p>\u003cp>\u003cstrong>按步骤举例正确的学习方式\u003c/strong>；\u003c/p>\u003cp>认知类的学习大家都会很多感悟，其实运动技能同样也可以采用费曼学习法\u003c/p>\u003cp>第一步我最近确立的学习目标是前臂倒立\u003c/p>\u003cp>第二步我要充分理解这个体式，需要具备哪些能力，要做到这个动作之前得具备肩背肌肉耐力达到什么标准，骨骼关节需要处于什么样的状态，应用什么样的呼吸才能做到，这个动作退阶我可以做什么，进阶我可以做什么，哪些动作训练可以帮助我达到这样目标，\u003c/p>\u003cp>第三步 输出，我自己按照理解去做动作，并且通过怕视频用过第三者视角去观察自己动作是不是到位，反复的输出，量变到质变，到自己真的做到以后就用别人能理解的语言甚至针对别人的情况去教授他们做到这样动作\u003c/p>\u003cp>第四步 请资深的同学，老师对我的动作反馈，针对性的去改善\u003c/p>\u003cp>第五步 通过自己的学习过程，总结归纳自己独有的方法和经验，努力找出底层逻辑，在精进的练习去举一反三。\u003c/p>\u003ch2>\u003cstrong>适用边界\u003c/strong> \u003c/h2>\u003cp>费曼学习法的适用边界还是很广的，认知类，运动类，艺术类等等都可以用上 如果有关注学习大脑科学的朋友，会发现其实这个方法和刻意练习一万小时定律从新手到大师的过程是息息相关的，是各个领域学习者通用的高效学习方法。\u003c/p>","interaction":"\u003cp>\u003cstrong>a1\u003c/strong>了解了费曼学习法的五个步骤，我们来对照自己最近一个月内一次的阅读或学习，工作经历，我们一一对应有做到哪几个步骤呢？哪些步骤还有欠缺？\u003c/p>\u003cp>分组讨论 请组员分享 根据组员分享\u003c/p>\u003cp>\u003cstrong>a1+ \u003c/strong> 结合费曼学习法的五个步骤，针对刚刚学习者具体经历，可以这样来调整或者精进我们的学习。。。。。。。。。。使之更有效率，更能指导实践 。。。\u003c/p>\u003cp>学习者：\u003cstrong>a1\u003c/strong>\u003c/p>\u003cp>1确定目标学习小儿推拿\u003c/p>\u003cp>2开始收集相关信息归纳整合\u003c/p>\u003cp>3开始在孩子身上实践\u003c/p>\u003cp>4根据孩子的反馈不断精进\u003c/p>\u003cp>5归纳总结成自己的经验\u003c/p>\u003cp>\u003cstrong>a1+\u003c/strong>\u003c/p>\u003cp>接下来想再分享给更多有需要的朋友，得到更多的案例反馈.\u003c/p>\u003cp>希望再把这些经验进行总结并形成课程，通过课程分享获得变现\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1727145145000,"updated_at":1731827355000,"ria":true},{"id":17954,"topic":"知识内化的5个步骤","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"火火Esther","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>★★自我介绍 1分钟\u003cbr>1.梦想\u003cbr>大家好，我是火火，寓意“在黑暗中点火”。我的理想是帮助在婚姻家庭中痛苦挣扎的女性，走出黑暗，收获幸福。\u003cbr>我认为健康的个人是幸福家庭的基础。\u003cbr>因此，最近半年多，我一直在做的事情是：我创办了ChangeLife改变生命在线读书会，帮助自己坚持阅读，自我成长，也帮助他人成长。\u003cbr>\u003cbr>\u003cbr>2.困难\u003cbr>这个过程中其实我有3大挑战：\u003cbr>1）缺时间：全职带娃，时间零碎。\u003cbr>2）能力差：速度慢，一个人无法坚持。\u003cbr>3）不自信：从小语文最差。\u003cbr>\u003cbr>3.努力\u003cbr>因为太渴望解决我的问题。\u003cbr>所以，我都是趁孩子睡觉时间，起早熬夜。刚开始我只会原文复制粘贴做思维导图。后面参加了ria便签营，学会了用便签法。\u003cbr>\u003cbr>4.成果\u003cbr>现在就可以不经常熬夜了。\u003cbr>8个月来，每期坚持阅读，经历改变的人有 6个人，他们都提升了阅读速度，改善了夫妻或者亲子关系，现在可以做领读，在线讲解了。\u003cbr>\u003cbr>这八个月共有200多人参与，还有很多人无法坚持，为了帮助到更多人，我决定继续提升自己的能力，所以今天我站在了这里。\u003cbr>\u003cbr>\u003cbr>\u003cbr>★★★拆书和拆书帮是什么？ \u003cbr> 2分钟\u003cbr>\u003cbr>1.拆书是\u003cbr>\u003cbr>who针对对象和中心：成人学习者，重点不是知识，是人。\u003cbr>what一种学习方法\u003cbr>why目标：提升能力，解决问题\u003cbr>how分类：把知识关联学习者经验，规划实操。体现在：\u003cbr>1）个人的方法：ria便签法，达到效果：读一本书，达到参加同类主题培训的效果。\u003cbr>2）集体的方法：拆书家。一位拆书家能用一本书，加工成一次现场学习，引导和促进一群人把知识拆为己用。\u003cbr>拆书家的价值：不亚于一位培训师带来的培训效果。\u003cbr>\u003cbr>where在哪里学？\u003cbr>拆书帮：\u003cbr>使命：是帮助学习爱好者成为拆书家。\u003cbr>性质：是一个非盈利的兴趣社群。\u003cbr>运营：具体运营是在各地设立实体分舵（俱乐部）。\u003c/p>\u003cp>我个人体会到的特色：\u003cbr> 1.便签营：\u003cbr> 课程设计循序渐进，专业拆书家教练一对一专业点评作业，回答问题。\u003cbr> 2.师徒制，每个人都有一个拆书家做师父，给与专业引导。\u003c/p>","ratings_count":2,"texts":[{"id":22192,"quote":"\u003cp>★I 拆页原文\u003c/p>\u003cp>费曼五条重要的建议\u003c/p>\u003cp>费曼曾对自己的学生说：“从体系化的角度看待知识时，我们比碎片化的学习获得了无数的好处，其中最大的好处是能看清不同知识的内在层次和结构关系，方便我们进行总结和升华，然后对外传播知识。”\u003c/p>\u003cp>这就是知识的内化。对此，费曼提出了五条重要的建议：\u003c/p>\u003cp>第一，使用笔记记录知识的核心要素。\u003c/p>\u003cp>学习时要养成记笔记的好习惯，把重点内容尤其核心的要素记录下来。这既帮助我们在后面对知识的加工，也是一种辅助记忆的手段，能加深我们对知识的印象。\u003c/p>\u003cp>第二，一定要大幅度地整理所学的知识。\u003c/p>\u003cp>“大幅度”的定义是，我们对输入进来的信息和资料进行一次深层次和全面的过滤，删除不需要的内容，并把高价值的知识以一种严谨的逻辑整理出来，赋予清晰的层次感。\u003c/p>\u003cp>第三，对知识进行结构化的归纳与理解。\u003c/p>\u003cp>通过自身的角度和需求，展开脑力活动，以结构化的方式对知识进行归纳与理解，形成自己的见解，并用精准的语言重新阐述。\u003c/p>\u003cp>第四，输出和发布自己所理解的知识。\u003c/p>\u003cp>把归纳整理好的知识发布出去，或者讲述给别人，收取人们的反馈。这么做既验证自己的理解，也能在公开或非公开的沟通中听取其他人的想法，补充自己没想到的地方，开阔视野。\u003c/p>\u003cp>第五，对知识进行简化、吸收和记忆。\u003c/p>\u003cp>最终，对学习和输出知识所得的“精华版本”进行简化、吸收和记忆，产生自己的知识体系，创造新的知识，并且为己所用，转化为长时记忆。到这时，我们的学习才算真正高效地完成。\u003c/p>\u003cp>对于这五条建议（五个步骤），费曼格外强调它们的相互关系。从第一步到第四步是递进和逐层依赖的关系，而第五步是我们的最终目的。即，我们在运用费曼学习法的过程中所学到和创造的知识最终都是以分享和帮助到别人并形成一个属于自己的知识体系为目标的。我们也应该致力于让晦涩高深的知识易于理解，在更广泛的人群中普及。这正是费曼推崇“以教代学”的目的之一。\u003c/p>","explains":"\u003cp>知识内化的五个步骤\u003cbr>R《费曼学习法》\u003cbr>\u003cbr>what：知识内化的五个步骤\u003cbr>\u003cbr>拆页认为知识的内化是：\u003cbr>搞清内在逻辑：不同知识的内在层次和结构关系。\u003cbr>why\u003cbr>1.好处：内化是系统化的学习，能帮助我们提炼精华，传播知识。\u003cbr>2.恶果：碎片化的知识无法形成体系。\u003cbr>\u003cbr>how：记录整理三次复述\u003cbr>曼提出了五个步骤：\u003cbr>“重整自我，分享精华”\u003cbr>1.重：记录重点\u003cbr>记笔记要抓重点抓核心要素。\u003cbr>好处：\u003cbr>1）帮助后期加工知识。\u003cbr>2）加深对知识的印象。\u003cbr>\u003cbr>2.整：整理逻辑\u003cbr>“大幅度”整理：\u003cbr>1）删除不需要的：全面深入过滤，删除不需要的知识。\u003cbr>2）整理高价值的：逻辑化严谨，层次感清楚\u003cbr>\u003cbr>3.自我：自我复述\u003cbr>根据自己的需求，归纳理解，用自己的话准确的语言复述。\u003cbr>\u003cbr>4.分享：分享复述\u003cbr>获得他人的反馈，验证自己的理解，查漏补缺。\u003cbr>\u003cbr>5.精华：精华复述\u003cbr>提炼精华，做到简化，吸收，记忆。形成自己的知识体系，创造新知识，让自己能够应用。\u003cbr>完成以上五步，我们才算完成真正的高效学习。\u003cbr>\u003cbr>五个步骤相互关系很重要：\u003cbr>从第一步到第四步是递进和逐层依赖的关系，而第五步是我们的最终目的，即分享和帮助别人，并形成自己的知识体系。\u003c/p>\u003cp>where\u003cbr>最后，我觉得这个方法适用于大部分领域的学习，包括书籍，知识，技能等。只是对性格害羞，不擅长表达的人，可能挑战比较大一点。\u003c/p>\u003cp>\u003cbr>★我的实操案例：\u003cbr>用费曼学习法做家庭物品分类定位图表\u003cbr>1.记录重点：把需要整理的重要物品种类大体写出来。\u003cbr>2.整理逻辑：\u003cbr>去掉不需要的种类。\u003cbr>留下需要的，并且写出思维导图：包括大小分类和定位。用了金字塔的方法。\u003cbr>3.理解复述：\u003cbr>自己和自己讲了一遍，发现了自己有两三个地方记不清楚，做修正，让自己容易记住。\u003cbr>4.分享复述：\u003cbr>讲给孩子们听，他们可以记住大分类，并画图。但是发现全部在一个图，他们不容易记住。需要把他们自己的东西分类出来，便于记忆和之后他们自己管理自己的物品。于是我决定分两个图表：孩子物品管理，大人物品管理。\u003cbr>5.精华复述：\u003cbr>再次把孩子的部分讲给他们听，发现我应该按“人”分类，而不是按物品大小分类。他们容易记住：自己的，哥哥（妹妹）的，共同的。最终他们全部记住能讲出来，并且商量达成一致：关于公共物品管理原则：谁拿出来玩，谁负责放回去。\u003cbr>大人的部分，由于孩子玩去了，我再次讲给自己听了一遍，查漏补缺，画了浓缩图表。\u003cbr>最终效果：原本脑袋一团乱麻，现在每个东西都能讲出来类别和具体位置。心里感觉无比清晰和踏实。\u003c/p>","interaction":"\u003cp>A1\u003cbr>★故事：\u003cbr>\u003cbr>今年5月底开始，在线学习蒋佩蓉老师的《智慧父母12商》督导课程。目前已到尾声，我发现自己除了认真按时完成了作业，参加了每周在线讨论，还不能把每一课精简复述，不能形成自己的知识体系。\u003cbr>★反思\u003cbr>原因有自己的态度，决心等多方面。方法上的原因，对应拆页，有以下：\u003cbr>1.只听课，没有写笔记。\u003cbr>2.只听课，没做思维导图。\u003cbr>3.虽然有理解复述，即准时完成写作业。但是，质量不高。\u003cbr>4.分享互动缺了一半：课程设计了总督导每周在线答疑，没有提问，也没有听回播。只参加了小组每周讨论。因此无法高质量查漏补缺。\u003cbr>5.由于前四步是逐层是环环相扣的关系，导致了我无法提炼精华，讲不出来系统化的知识。\u003cbr>\u003cbr>\u003cbr>A2\u003cbr>如何用费曼学习法复习RIA便签法\u003cbr>目标：3个月内用，用此方法来复习便签法，达到每一课都能精准的用自己的话复述，讲给我的孩子听，让他们能听懂。\u003cbr>1.记录重点：重新听一遍课。抓重点的，特别是我的卡点记录。\u003cbr>2.整理逻辑：去掉不需要的，留下精华，每一课都做一遍思维导图。\u003cbr>3.理解复述：录短视频讲，发现卡点，补充修正笔记和导图。\u003cbr>4.分享复述：对孩子讲，找出让他们不明白的卡点，修正笔记和导图。\u003cbr>5.精华复述：讲给孩子听，确保他们都能听懂。最终修正简化成自己能长时记忆的知识。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1723492247000,"updated_at":1723772866000,"ria":true},{"id":17621,"topic":"如何实施费曼学习法","learn_goal":"","remark":"倡导以教为学，以输出倒逼输入，提升学习效能","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"璞玉浑金","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>大家好，我是璞玉浑金，广州80后。名号取自我的姓名，更因它的寓意——未经雕琢的玉石&amp;未经提炼的黄金，外表朴素，内在却闪耀着高贵真实的光芒。\u003cbr>我有三个标签：\u003cbr>1.爱家庭的二孩父亲。我希望以身作则，去照亮孩子成长的道路。\u003cbr>2.爱哲学的数学教师。二十载跨学段教育，融哲学于教学，个性鲜明。\u003cbr>3.爱拆书的金庸迷。侠之大者，为国为民。金庸大侠对我影响深远。我将开启拆书分享之旅。\u003cbr>我崇尚终生学习，一直奋斗在路上，欢迎大家多交流，共进步。\u003cbr>\u003c/p>","ratings_count":1,"texts":[{"id":21818,"quote":"\u003cp>【R阅读原文拆页】1-2分钟\u003c/p>\u003cp>主题《费曼学习法》“如何实施费曼学习法”\u003c/p>\u003cp>1.3如何实施费曼学习法\u003cbr>我并不是很在乎学习的外在形式，但很在乎学习的内在核心一如何真正学会。我会用费曼学习法，正是因为费曼学习法的本质是一种学习的思维模式和行为模式，而不是一堆华而不实的工具。在运用费曼学习法之后，我才真正理解了写作业、考试的意义。\u003cbr>1.3.1费曼学习法的实施步骤\u003cbr>严格来说，费曼学习法并不是一种方法，而是一-种思维模式。这种思维模式会不自觉地影响行为模式。\u003cbr>但如果直接把费曼学习法说成一种模式，难免有些难以理解,也难以落实。所以，我们在应用费曼学习法时，可以按照以下步骤进行。\u003cbr>\u003cbr>1.制定目标\u003cbr>学习之前，我们首先要制定一个明确的目标。制定学习目标应当遵循SMART原则，也就是目标应当是具体的( Specific)、可以衡量的( Measurable)、可以达到的( Attainable)、具备相关性的( Relevant )以及有明确截止期限的(Time-bound)。有了目标之后，我们还要制订具体的行动计划。\u003cbr>2.尝试输出\u003cbr>感觉自己学会后，我们可以尝试输出学习内容，验证自己有没有学会。在课业学习方面,除了向别人分享外，我们还可以通过写作业、考试等方式来输出和验证学习成果。费曼十分喜欢用口语阐述的方式来写作，甚至在写严谨的科学论文的时候也是如此，他还喜欢利用图表来展示晦涩复杂的量子力学。\u003cbr>3.发现问题\u003cbr>有了第2步的输出后，我们就会发现自己没掌握知识的原因可能是多方面的，有可能是记忆问题，即自己没记住;有可能是理解问题，即自己没有真的理解知识;也可能是视野问题，即自己知识的边界没有打开。这时候我们可以有针对性地进行复习。\u003cbr>4.真正掌握\u003cbr>经过第3步后，我们对知识的理解将会更进一步，会发现哪些知识是最重要的。当然，这时候我们也不要自满，还需要再次验证自己有没有真正掌握。只有能融会贯通，才算真正掌握了知识。\u003cbr>当我们掌握了费曼学习法的精髓，能熟练使用费曼学习法时，不必拘泥于这4个步骤，只要遵循费曼学习法的基本原理就可以了。\u003cbr>但如果是初学者，之前从来没有接触和应用过费曼学习法，一开始可以严格按照这4个步骤实施,熟练之后再尝试改变。\u003c/p>","explains":"\u003cp>【I重述知识点】5分钟\u003c/p>\u003cp>WHAT \u003cbr>学习是一个非常主观的行为，没有主动思考就没有学习。还记得以前读书的时候，遇到困难的题目，我们苦苦思索，最后豁然开朗，解题印象是否会特别深？当我们洋洋得意，把问题解答过程教会给身边同学，此时我们无疑会留下更为深刻的印象。这种以教为学的方法，其实就是费曼学习法。\u003cbr>\u003cbr>WHY\u003cbr>学习金字塔告诉我们，任何被动学习能留存的比例是极少的，即使是在旁边观看演示，能留存的比例也低于50%。那怎么才能提高留存率呢？主动学习！在说中学，做中学，教中学。这些行为其实都是主动学习，尤其是最后一项——教别人学，能达到90%以上的留存率。费曼学习法就是倡导以教为学，以输出倒逼输入，从而在大脑中留下更为深刻的痕迹。与此同时，也能倒逼自己更好地去理解学习内容。\u003cbr>\u003cbr>HOW\u003cbr>1.制定目标\u003c/p>\u003cp>就是学什么，或要干什么。还可以使用SMART原则（Specific具体、Measurable可测量、Attainable可实现、Relevant相关性、Time—based时效性。）\u003cbr>比如“我想在一周内学会使用费曼学习法。”\u003c/p>\u003cp>2. 尝试输出\u003c/p>\u003cp>创造一个场景，在这个场景中将自己学到的知识讲授给&quot;别人&quot;，比如培训他人、写公众号、录视频；\u003cbr>比如“在完成启动营作业的时候，我刚好要进行费曼学习法的讲解，现在我就在用语音输入，讲给别人听”\u003cbr>\u003cbr>3.发现问题\u003cbr>无论是在教授的过程中说错的、说不清楚的、模棱两可的都需要在这一步中进行强化。\u003cbr>比如“我发现自己在介绍费曼学习法的概念时并太清楚，为什么会不太清楚呢？”\u003cbr>\u003c/p>\u003cp>4.真正掌握\u003cbr>对知识进一步理解，且将学习内容进行提炼、简化，用自己的语言通俗易懂表达出来。这有一个重点，就是简化到可通过类比，让一个非专业人士都能听懂。此时才真正掌握了这门学习方法。\u003cbr>比如：&quot;我再看了一下原文，发现费曼学习法就是以教为学的方法，以输出倒逼输入的方法，有目标、教学、纠错、简化这4个步骤，教学有利于暴露问题，从而纠错，纠错后才可优化简化，再进一步去教学，把它讲给其他人听。如此循环，从而真正学会。\u003c/p>\u003cp>\u003cbr>WHERE\u003cbr>只要是认定了有价值的内容，希望以此为学习目标，都可以使用费曼学习法，帮助自己更好地理解掌握。如果时间不允许，或只需要浅层了解的内容，可不用费曼学习法，以避免占用大脑内存。\u003c/p>","interaction":"\u003cp>【A1联系具体经验】1-2分钟\u003c/p>\u003cp>一直以来有读书的习惯。去年把《好好学习》这本书重新拿出来，想再研读一下，从中获得一些可借鉴的养料。这一次我读得非常认真，读得很慢。在读的过程中，遇到疑惑的地方或有价值的地方会做笔记，做批注，与作者进行对话。这的确让我对整本书的理解提高了一个层次。但是隔了一段时间之后，我发现自己能记住的东西并不多。在这里，虽然我是在主动学习，并且在学习过程中有自己的思考，但我并没有以教为学，也就是我缺乏教学这个输出环节，也就没办法去纠错，更没有把它简化。从整个内容的理解看，简化应该是非常重要的一个环节，因为如果能把内容类比简化说给非专业人士（或小孩）听，那么对这个内容的理解把握，应该会达到一定深度。而且在简化过程中是需要大脑参与思考，加工，更容易形成深刻记忆。\u003cbr>\u003c/p>\u003cp>【A2具体应用】3分钟\u003c/p>\u003cp>为了更好的践行费曼学习法，把书的价值真正发挥出来，我加入了便签营，后来加入拆书帮。在这里有许多以教为学的机会，只要跟上节奏，就可以践行费曼学习法。为了更好地在拆书学习中，使用费曼学习法，提升学习效果，我制定了以下计划：\u003cbr>1.本周日——周五，每天回顾费曼学习法步骤，用自己语言解释各环节；\u003cbr>2.对照片段原文，看是否有出入，如理解不到位，重新尝试解读；\u003cbr>3.把内容进行加工整理，争取简化，讲给孩子听，看是否能理解。\u003cbr>4.在工作中，每次备课时，思考\u003c/p>\u003cp>所教内容怎么用自己的语言表述，并尝试说给自己听。最最重要，抓住简化这个环节，把内容浓缩，形象化、故事化、模块化，类似于之前的“将军饮马”问题（水、相信光），更容易理解、记忆。\u003c/p>\u003cp>【结束语】1分钟\u003c/p>\u003cp>最后总结一下今天的拆书：我们学习了“费曼学习法”，知道了主动学习的价值。没有主动思考就没有学习，没有输出就没有学习。通过几个步骤：1.制定目标，2.尝试输出，3.发现问题，4.真正掌握，如此践行刻意练习，就能大大加强学习效果，达到真正掌握的目的。让我们都能学会在说中学，做中学，教中学，并保持这个好习惯。\u003c/p>\u003cp>我今天的分享就到此结束了，希望这个“秘籍”会对各位小伙伴有帮助。下次有机会再让我们一起享受神奇的拆书之旅吧！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1716092255000,"updated_at":1716954322000,"ria":true},{"id":16597,"topic":"如何快速理解书中的知识","learn_goal":"","remark":"  阅读是一件惬意的事，但我们很多人都不知道怎么阅读，且读完尾就忘了前。我们怎样更好更好的去理解书中的知识点，并更好的运用到工作和生活中呢？让我们一起来学习《费曼学习法》中的《得到关键问题的反馈》——“如何快速理解书中的知识”吧，通过本次学习，可以快速理解书中的知识点，并让学习内化成自我的使用。\n\n","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"金老师","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>开场：又到我们每个星期四线上学习时间了，今天给大家带来如何快速理解书中的知识，来自《费曼学习法》\u003c/p>\u003cp>那还是用三个标签介绍下我自己。\u003c/p>\u003cp>我是金炳云，金是黄金的金，彪炳的炳，白云的云。\u003c/p>\u003cp>M;我是一名咨询师也是以为职业经理人，目前是众智图书馆的副馆长通商孵化器创业导师，负责众智图书馆的管理、活动筹备策划、企业读书会推广工作及一些创业咨询工作。\u003c/p>\u003cp>T:我擅长企业股权激励、阿米巴经营模式，对企业管理、股权架构激励等有一定的了解与研究，曾经服务过生产型、餐饮、建筑、服饰连锁等多种业态的企业\u003c/p>\u003cp>V:我目前在武汉管理10个公益型社区图书馆，我们图书馆有些活动场地可以提供给大家作为组织活动使用。同时，如果大家有管理类的一些问题，我也可以给大家一些建议和解决思路，有需要的可以联系我，谢谢！\u003c/p>","ratings_count":1,"texts":[{"id":20703,"quote":"\u003cp>R\u003cstrong>【\u003c/strong> 原文片段\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>得到关于问题的反馈\u003c/strong>\u003c/p>\u003cp>需要一提的是，有很多公认的&quot;好知识&quot;盛名之下其实难副，权威的观点和论证也并非不存在问题，复述能帮助你尽可能发现那些与实际应用不相符合的内容。在复述时你可以对知识中的某一个论点、论据或论证逻辑提出自己的疑问，再从温习中找到反馈。这能为你养成很好的学习习惯。\u003c/p>\u003cp>第一次复述时，应该如何实施从开始到结束的整个过程？我们可以分成三个阶段：\u003c/p>\u003cp>第一个阶段：凭印象复述。\u003c/p>\u003cp>开始复述时，可以描绘一下那些你自己记得最清楚的内容，把印象深刻的部分讲述出来。比如特别的观点、有趣的案例和别出心裁的论证等。不用顾虑说得是否准确，要自由、大胆和随心所欲地讲出自己的印象。根据这些讲述出来的印象，回头可以去整理这些知识点，进行二次学习和比对。我有一个习惯，了解到一个知识时我先快速自己把它讲一遍，然后统计哪些讲得对，哪些偏离了原意，回头再根据这个统计重点学习。\u003c/p>\u003cp>第二个阶段：复述中提出问题。\u003c/p>\u003cp>第二个阶段并不是在几天之后，而是随后进行，也就是当你对自己讲完对知识的初步印象后。比如喝一杯茶，在5分钟、10分钟之后。这时我希望你的手上多了一张纸，上面记着你在第一个阶段复述时印象深刻的知识点。这个阶段的复述不仅仅是重温你刚刚学到的内容，而是有意识地将它们与自己过去已知道的知识相结合，进行对比，怀疑，分析，看能否用自己的逻辑很好地把它们融合到一起。如果不能，针对这些知识点提出新的问题，写下一系列的&quot;为什么&quot;。你要解决这些&quot;为什么&quot;，才能把知识变成你自己独有的智慧，并且成功地输出给别人。\u003c/p>\u003cp>第三个阶段：复述中加入自己的观点。\u003c/p>\u003cp>最后一个阶段是为了完成我们对于知识的理解和升华。通过对所学内容的复述，一边说一边对比检查，把自己的观点加进去，实现新知识与自身已有的知识系统的衔接。比如，我学习了如何维修汽车发动机，便和自己开车时总结的经验结合起来，为一些过去的疑问找到了答案，对汽车便有了更深的见解。当你在新知识的基础上形成了自己的观点，才能到各个分享平台传播你的见解，输出你的观点，从更大的群体中获得更广泛的反馈，加速自己的进步。\u003c/p>","explains":"\u003cp>\u003cstrong>I 拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>我看大家都看完了原文片段，下面我来和大家分享一下我对这段话的解读。\u003c/p>\u003cp>\u003cstrong>【技能点】【I】拆书家讲解引导-预防异议\u003c/strong>\u003c/p>\u003cp>（一般做法）\u003c/p>\u003cp>我们很多人看书都是凭感觉和兴趣看书，包括我之前也是一样，对阅读没有什么规划，而且书看完也就完了，没有在意理解与使用，即使自己觉得特别好的书也只是当时兴奋，三五天后就遗忘了。有时碰到理解困难或理论性书籍更是无法读完，甚至感觉枯燥乏味，对于自己的理解或使用更是无从谈起。\u003c/p>\u003cp>（后果）\u003c/p>\u003cp>这样读书的后果只会是看了后面忘了前面，一本书能记住三个知识点已经不错，甚至有的阅读毫无价值，甚至是浪费时间。\u003c/p>\u003cp>（反例）\u003c/p>\u003cp>我也算是爱读书之人，但读书依然是没有清晰规划，更多的是兴趣。\u003c/p>\u003cp>如：我是从事股权激励和阿米巴经营咨询工作的，我印象最深的就两本书，《合伙人制度》 和《阿米巴经营》，其实我每年阅读量至少也有三五十本，但在上个月参加一次学习时，老师说：“请问金老师读过的书有哪些哪？”，我想了半天支支吾吾的说：“《合伙人制度》、《阿米巴经营》、最近读的《这样读书就够了》、《复盘成长》、《正面管教》等”，依然不记得多数书的名字。\u003c/p>\u003cp>（What）\u003c/p>\u003cp>其实，我和多数人读书一样，读完也就结束了，可能和自己工作相关或有相关经验的内容稍有领悟，其他的过了也就过了，从来没想过去怎么内化为己用，或怎么记住他。\u003c/p>\u003cp>那正确的读书方法或者说怎么去更好理解书中知识点，为我所用呢？可以运用《费曼学习法》中关于《得到关键问题的反馈》中的做法：复述反馈学习法。\u003c/p>\u003cp>（How）\u003c/p>\u003cp>一、读完后凭印象去复述一遍。复述其实就是理解的过程，如果不能很好理解书中知识点是很难复述出来的。\u003c/p>\u003cp>二、复述后思考一下，结合自己的经验提出相关问题。书中为什么这样讲？我以前又是怎么做的？我以前的做法和现在书中知识点有何相同与不同？写下自己的思考，一个一个的解答。\u003c/p>\u003cp>三、思考完后在来复述一遍，并加入自己的观点。根据自己的思考和理解，在复述中加入自己的观点和总结，并运用到生活和工作中，成为自己的想法或观点部分。如，我们有新的观点后运用到生活或工作中，会不会得到不一样的答案和结果？\u003c/p>\u003cp>（反例变正例）\u003c/p>\u003cp>结合书中方法，我以后阅读时尽量会选择与自己工作或对生活有指导性的书籍，并在学习完后加以理解运用到工作和生活中。如：我在发现自己阅读的问题后，决定加入拆书帮，并要求自己在今年12月31日前成为三级拆书家，且要将自己读过的书拆成读书课，分享出去，让更多人受益。现在在拆书帮想学习方法和文中表述的也是基本一致，1、结合书中知识做自我复述，也就是I。2、加入自己的思考与问题。3、把读的书拆成读书课分享给爱学习的读者和同事。\u003c/p>\u003cp>（why好处）\u003c/p>\u003cp> 这样做的好处能让我更深刻的理解书中的知识点，也能将书中知识点能运用到工作和生活中，并能快速提升自己的阅读理解和工作能力。\u003c/p>\u003cp>（where）\u003c/p>\u003cp>这种学习方法不仅适合阅读、培训学习，也是适合写作及日常工作总结的。\u003c/p>\u003cp>那肯定有伙伴会说，我的理解能力有限或者说一本书内容太多，复述和理解比较难，该怎么办呢？首先，在书籍选择上我们可以选择和我们工作和生活上息息相关或者说有帮助的书籍。其次，将书中有指导作用的知识点或方法分段理解。最后，可以将书中指导思想或有用的方法、技巧与最近生活和工作相结合，有用或有帮助的尝试运用，而且也可以运用《费曼学习法》中的以输出的方式倒逼自己学习，用传授、培训输出的方式去理解和输入知识。\u003c/p>","interaction":"\u003cp>A 学习者拆为己用\u003c/p>\u003cp>\u003cstrong>【技能点】【A2】分步催化1，运用显像提问法。\u003c/strong>\u003c/p>\u003cp>接下来，我们请大家想象一下，在未来的一周或一个月内，可能是我们正在读的一本书、或将参加的一次培训、或者是将要写的一篇总结，只要找到这个情景即可，把情景写下来就好了。这个情景要有具体的时间地点待会我会请一个小伙伴来分享一下。\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003c/p>\u003cp>孟碟：将在下星期六参加楚师联盟的一次关于培训师的培训学习\u003c/p>\u003cp>\u003cstrong>【技能点】【A2】分步催化2，引导学习者将刚才记下的情景加工成符合拆页所示方法的例子。\u003c/strong>\u003c/p>\u003cp>大家想到的都跟今天拆页中的学习有关，这确实是我们XX这个方法的一个应用场景。\u003c/p>\u003cp>接下来我们可以把我们刚才想到的这个情况，加工一下，加工成具体的例子。比如你可以想一想，如果今后，你遇见了这种情景，请大家小组内分享一下你针对这个将来可能出现的场景，拟定的一段使用计划,我们的时间是3分钟。\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003c/p>\u003cp>孟碟：结合今天学习的技巧，1、将在参加完培训学习后回来要做一个复盘，将培训类容做一个梳理。2、将结合培训学习提出自己的问题，吸收消化补充自己的知识体系。3、将在以后自己的拆书课或职业咨询中融入新知识，形成自己的知识结构，输出给更多人。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>感谢孟碟找了这样一个适用的场景，一次培训学习的场景，这就是我今天分享到此结束,谢谢大家\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1694159811000,"updated_at":1695378850000,"ria":true},{"id":16119,"topic":"如何抵抗遗忘？","learn_goal":"","remark":"我手机呢？我钥匙呢？我刚想说什么来着？\n\n\n\n这个时代，记忆力不好，已经成为一种普遍的都市现代病。每天不感叹几句“我又忘了”“我怎么又忘了”，仿佛都不好意思说，自己是个现代人。\n\n很多人会喟叹“是不是自己老了”“大脑不灵光了”，但其实，这是非常正常的情况。\n所以，记忆力是什么？我们又要如何提高记忆力呢？\n\n\n6月18日下午14:30来安次区阅读咖啡二楼，听一听一级拆书家宁静老师讲解提高记忆效率的方法~压缩记忆法。\n\n本次课程将为您介绍一种高效的学习记忆方法，这种方法选自知名物理学家费曼的学习法，它可大大提升学习工作效率。我们将带您了解压缩记忆法的原理和操作步骤，帮助您快速掌握并记住大量的知识点。无论您是学生还是从事各类职业的人士，本课程都能为您带来启发，助您轻松学习和工作。\n\n71687060431528_article7_866.jpg\n\n拆书家简介：\n\n宁静，\n\n中学高级教师\n\n家庭教育指导师\n\n具有37年教育经验\n\n一级拆书家\n\n【活动时间】：6月18日周日下午14：00-16：00\n\n【活动地点】：廊坊市安次区光明西道悦读咖啡二楼","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"宁静@微光","city":"廊坊市"},"club":{"name":"廊坊风陵分舵","city":"廊坊"},"prologue":"\u003cp>\u003cstrong>图书介绍\u003c/strong>（FAB法）（2分钟）\u003c/p>\u003cp>今天我带领大家拆解的书籍是《费曼学习法》，主题：”提高记忆效率的方法～压缩记忆法：\u003c/p>\u003cp>特征：这本书的作者是一位微博教育博主@写书哥，作者在微博影响力很大，全网有近百万粉丝。\u003c/p>\u003cp>优势：\u003c/p>\u003cp>1、 费曼是诺贝尔物理学奖获得，他创造的费曼学习法风靡全球，很多成功人士包括比尔盖茨、乔布斯都很崇拜他。所以这本书比一般介绍学习法的书籍更有影响力。\u003c/p>\u003cp>2、 这本书的作者就是凭借费曼学习法考上清华大学的，所以这本书的实践性很强。\u003c/p>\u003cp>3、利益：这本书不仅介绍了费曼学习法的内涵应用，还总结出如何用费曼学习法破除学习心理魔咒、调整情绪、有效自学、可以帮助大家找到学习的“捷径”，变得会学习、爱学习。\u003c/p>","ratings_count":1,"texts":[{"id":20208,"quote":"\u003cp>\u003cstrong>R环节\u003c/strong>：请大家阅读拆页，看看这个内容讲的是什么（2分钟）\u003c/p>\u003cp>3.2.6压缩记忆法\u003c/p>\u003cp>在学习过程中，我们有大量知识需要记忆。有些需要记忆的知识是有逻辑的，记忆起来相对比较容易 有些是没有逻辑的，记忆起来可能让人很痛苦。对于一些没有逻辑的知识，我们可以采用压缩记忆法。\u003c/p>\u003cp>在运用压缩记忆法时，我们可以按照以下步骤进行。\u003c/p>\u003cp>1.归类\u003c/p>\u003cp>我们首先要将记忆的内容归类。将同类内容放到一起记忆，可以提高效率。例如，我们背诵元素周期表时，可以按照列来记忆。惰性气体元素中的氦，氖，氩、氨，氙可以集中记忆:科学常识中的太阳系八大行星也可以放到一起记忆\u003c/p>\u003cp>2.压缩\u003c/p>\u003cp>对于归类后的内容，我们需要进行分析，去掉重复的部分，从而实现压缩。分析的方法有很多，我门可以从汉字构成、词语组成等角度进行分析。\u003c/p>\u003cp>例如，氦、氖、氩、氪、氙具有相同的部首“气”，可以去掉，只记忆&quot;亥乃亚克山”。“魑魅魍魉”具有有相同的部首“鬼”，去掉通过整理后，就变成&quot;离未罔两”。\u003c/p>\u003cp>太阳系的八大行星的压缩比较复杂。其中，水星、金星、火星、大星、十星都具有“星”字:天王星，海王星包含”王星”两个字:上球和其他行星的名字没有相同之外，所以，整体可以压缩为“水金记地球火木十天海千星”。\u003c/p>\u003cp>3.整理\u003c/p>\u003cp>如果压缩后的内容比较长，我们还需要进行整理。同时，我们还可以调整顺序，让语句押韵，让记忆的内容朗朗上口。\u003c/p>","explains":"\u003cp>\u003cstrong>I环节：\u003c/strong>讲解原文知识点（2分钟）\u003c/p>\u003cp>What：相信大家都看出来了，这个片段讲的是一种提高记忆效率的方法。\u003c/p>\u003cp>Why:这种记忆法可以变繁为简、变无序为有序。让知识或者事物记得住、记得牢。\u003c/p>\u003cp>（强调不这么做的坏处）想想我们是否见过有些学生特别用功夫，花在背诵记忆上的时间很多，但效果很差，于是就怀疑自己的能力，甚至产生厌学情绪。再比如作为企业员工，领导安排的任务很多，自己没记住，丢三落四，极大影响了信任度。再比如我们当老师的，新生入学后总是记不住学生名字，影响师生亲和度。以上这些都是没有掌握高效记忆的方法导致的。\u003c/p>\u003cp>How：那么今天我们学习的压缩记忆法具体怎么做呢，有以下三个步骤：\u003c/p>\u003cp>1、归类：”合并同类项“，有相同特征的重复的归为一类。\u003c/p>\u003cp>2、压缩：去掉重复的部分，只记忆不同的部分，减少记忆内容。\u003c/p>\u003cp>3、整理：调整顺序，押韵上口，甚至有趣。降低记忆难度。\u003c/p>\u003cp>举例1：记忆莎士比亚的作品得时候，我们把四大悲剧分为一类，哈姆雷特、奥赛罗、李尔王、麦克白。然后压缩，提取其中一个字，在整理顺序，于是可以变成：“”哈罗李白“”，就很容易记住。\u003c/p>\u003cp>举例2：记忆传统文化经典：《四书》为一类，《论语》《大学》《中庸》《孟子》，压缩整理后可变为“四叔猛抡大钟”\u003c/p>\u003cp>举例3：出门的时候常说的：“伸手要钱”也是用了压缩记忆法。身份证，手机，钥匙，钱包。\u003c/p>\u003cp>   Where： 这种方法适合逻辑性不强的，秩序混乱、没有规律的内容。 \u003c/p>","interaction":"\u003cp>\u003cstrong>A1环节\u003c/strong>（激活经验，显像提问）：（2分钟）\u003c/p>\u003cp>你过去的一个月中，有没有遇到过因为需要记的内容太多太乱无逻辑，而导致一团乱麻的事情？比如：老板给大家一张客户名单，让尽快背下来，；你参加同学聚会有10多个人，饭后你想回忆都谁来了，可怎么也想不全；你参加历史类的自学考试，需要记忆诸多历史事件，人物等，你一头乱麻，怎么也记不住……。\u003c/p>\u003cp>请大家思考1分钟，在组内分享自己的经历。代表发言\u003c/p>\u003cp>\u003cstrong>A1+环节：\u003c/strong>反思加工、分组讨论（7-9分钟）\u003c/p>\u003cp>如果时光倒流，让你再回到当初，还是那个时间、那个地点、那个场景，你用上今天学的压缩记忆法，你会如何重新来做呢？请一位同学说说。\u003c/p>\u003cp>\u003cstrong>小组讨论、提示每个人在组内分享\u003c/strong>\u003c/p>\u003cp> 代表发言\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1687936559000,"updated_at":1688721589000,"ria":true},{"id":15930,"topic":"如何找到真正的兴趣","learn_goal":"","remark":"宣传语：你是不是给自己立了很多的flag，又一个一个的倒下？你是不是每天徜徉在各种信息的轰炸中，又仿佛什么都没有抓到？如果你跟我一样，欢迎来听我的拆书《费曼学习法》之如何找到真正的兴趣，确立学习目标","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Chunling","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cu>自我介绍：\u003c/u>\u003c/p>\u003cp> 大家晚上好，我是黄春玲，今天是我第一次参加拆书帮的晋级。我的三个标签分别是瑜伽爱好者、行家茶道成员和打工人。\u003c/p>\u003cp>现在我来为大家介绍一下拆书和拆书帮。\u003c/p>\u003cp>拆书是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。拆书法分为个人学习的拆书法和组织学习的拆书法：\u003c/p>\u003cp>个人学习的应用就是Ria便签法，就是我手里拿的三种颜色的便签。那具体怎么应用呢，比如说我现在读一本书的片段非常有感触，那么R就是指我阅读很有感触的片段。于是我拿出三张便签，一张写I，I指的是用自己的语言讲解描述有感触的那个片段。还有二张便签就是A就是规划应用拆为己用。分二个部分。【A1】写过去我的相关经历【A2】写未来我的一个应用。这样的方法能够让学习者更好地把书中的内容应用到工作或者学习的实践中去，让人读一本书就能达到参加主题培训的效果。\u003c/p>\u003cp>组织学习的拆书法就是现场学习法，它是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮分舵是非营利性青年组织，使命是帮助更多学习爱好者成长为拆书家。拆书帮目前在全国有89家分舵，49家正式分舵，我们属于其中一个正式分舵，武汉珞珈分舵我们是全国最佳分舵，还有四十家筹备分舵。\u003c/p>","ratings_count":1,"texts":[{"id":20019,"quote":"\u003cp>我的拆页选自《费曼学习法》第四章。\u003cbr>为什么会选择这一章来拆呢？其实费曼学习法很多咱们的拆书老师都拆过，方法呢大家也是耳熟能详分四个部分，理解，以教带学，回顾，和简化。我拆的尹红心和李伟两位作者的《费曼学习法》这本书分为五个部分来介绍学习方法，增加了确定目标这一章节。为什么确定学习目标如此重要呢？\u003c/p>\u003cp>请大家阅读我为大家准备的原书片段，半分钟的时间，阅读完毕之后，请扣1示意我。\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>第四章 聚焦目标\u003c/p>\u003cp>我曾经对学生这样阐述“目标”这个词：“目标不是一个符号，也不是一个摆在那里的台阶，只要走过去、爬上去就好了。目标其实是一个动态变化的信标，它是随着人的思想、年龄的增长而变化的。\u003c/p>\u003cp>之所以告诉学生人的目标是动态的，是希望他们不要妄想长期对同一个目标保持专注。这不现实，尽管总有少数人能凭借坚韧的意志力做到这一点。但大部分人是“普通人”，每天的原始资本都是24小时，一种兴趣往往持续不了一两年，最务实的做法是——在这一两年的黄金时间内聚焦在一个正确的目标上，尽可能取得不凡的成果。事实上，许多精英人士就是这么做的，他们不是天才，却是学习的高手，在有限的时间内学到了比其他人更多的知识并应用到了实际的生活和工作中，得到了远远高过大多数人的收益。\u003c/p>\u003cp>这个答案就是：\u003c/p>\u003cp>他们善于抓住学习的黄金时间，将全部的精力聚焦于选定的目标之上，心无旁骛地把这门知识/技能学通、学精和化为己用。\u003c/p>\u003cp>为了定位真正的兴趣，不妨多给自己一些宽松自由的思考空间，深入分析那些自己喜欢的领域，查阅相关的资料，然后进行初步的尝试，从中找到自己学习的对象。\u003c/p>","explains":"\u003cp>好，我看到大部分小伙伴已经阅读完毕，接下来我分享下自己对这个片段的理解，这也是RIA的I环节。\u003c/p>\u003cp>(Why)：\u003c/p>\u003cp>为什么确定学习目标如此重要呢？\u003c/p>\u003cp>这个假期感谢拆书帮的组织我参加了线上私董会，不知道在场的小伙伴有多少人也参加了。案主的问题也引起了很多人的共鸣，在这个瞬息万变的社会，我们需要不断的学习，不断的进行自我的迭代，才能不被时代抛弃。我们想做的事情很多，而时间和精力又那么有限。大家给了很多如何规划人生目标的方法，我这里拆页的是如何规划学习目标，有诸多相似之处，当时我听了大家的建议也有很多感触。我相信如何学习确定目标，做自己真正感兴趣的事情，也是很多人的问题。\u003c/p>\u003cp>\u003cu>(What)：\u003c/u>\u003c/p>\u003cp>说到学习，我们每天都忙忙碌碌，参加各种培训，训练营，付费课程，又像什么都没有学到手？因为我们没有聚焦学习目标，进行真正的学习，真正的学习建立一套属于自己的，行之有效的思维框架，在有限的时间里学到更多的知识运用到实践中，解决生活和工作中的问题。\u003c/p>\u003cp>\u003cu>(How)：\u003c/u>\u003c/p>\u003cp>怎么能确认什么才是自己真正感兴趣的事情，聚焦学习目标呢？\u003c/p>\u003cp>第一步，认真审视你的计划是否能匹配已有的知识体系。我们有很多计划，甚至随时都会产生新的计划，怎么去聚焦呢，首先审视自己原有的知识体系是否与目标相匹配，为什么需要这一步？因为大脑喜欢熟悉的东西，我们要学习一种新知识时，用最直白的语言去阐述它时，大脑就会从记忆库中提取那些熟悉的信息，在旧的知识和新的概念中产生强大的关联，新的知识便容易得到大脑彻底的理解。\u003c/p>\u003cp>第二步，问自己这个目标现在不做会让你终生遗憾吗？如果大家还会觉得这个表述比较抽象，可以用排除法，排除掉可以做和非必须做的目标，剩下的就是应该聚焦的目标。\u003c/p>\u003cp>第三步，我们是否能够把自己的目标分解到每一天，当成每天最重要的事项来执行。如果你想做一个决定的时候，脑袋里出现了大量退缩的信息，比如今天要出差，明天要培训，后天要接孩子，各种原因把你劝退，那就不是真正的目标。真正的目标是要把这件事情当初每天做重要的事情，按照我们的规划实施和完成。当然这里的每天也可以是某一个固定的频率。\u003c/p>\u003cp>\u003cu> (Where)： \u003c/u>\u003c/p>\u003cp>学习是一件很鲜活的事情，它需要有应用场景，这个知识或者这个技能我们能在哪里使用，最好能经常应用得到，这才是真正好的目标。这个方法对于确认工作中的学习目标和生活学习目标都适用。\u003c/p>","interaction":"\u003cp>A1: \u003c/p>\u003cp>前面的便签里我提到了我是一个瑜伽爱好者，我练习近10年的瑜伽，参加过大班课，也上过私教课，曾经还系统的上过瑜伽的教练班。我学习瑜伽除了建立身心灵的连接外，还有一个目标是改善我的体态，但是10年来效果一直不是很明显。在今年夏天一个偶然的机会我在休假的时候参加了一个维密训练营，针对体态问题逐一训练，比如一字肩、马甲线、蜜桃臀，我参加的是一字肩。由于有练习瑜伽的基础，连续上了一个星期的课后我的圆肩驼背都有了明显的改善，其实最让我醍醐灌顶的是老师的一句话，她说“把你学习到的体式带到你的日常生活中去”。我练了很多年的瑜伽，练习是练习，生活是生活，我只在练习的时候按照老师的要求去做每一个动作，出了瑜伽室，我仍旧回到了我惯常的行动方式，脖子前倾，走路外八等等。结束了一个星期的密集训练后，我尽可能在每一天的走路、站立、甚至是坐立过程中，刻意练习我的背部肌肉，把它当成我每天最重要的事情。现在我的体态有了明显的改善，甚至有好久不见的朋友说，看你走路的样子，都没认出来是你。\u003c/p>\u003cp>\u003cu>反思\u003c/u>\u003c/p>\u003cp>1、 我选的目标跟我的知识匹配，我对训练中老师的口令，具体练习到的肌肉，发力点部位要求都能很快理解并准确练习\u003c/p>\u003cp>2、 这件事不做我会后悔终生，大家都能明白美是女人的终生事业，体态的改善不仅关乎美，还有健康，这是我一直以来都想做而没有成功的事情，\u003c/p>\u003cp>3、 能够把练习当成每一天最重要的事情，只有抓好机会我就会有意识的提醒自己挺胸、收腹、沉肩，所以学习效果非常明显，也给我很好的正反馈让我把随时随地练习变成每天的日常。\u003c/p>\u003cp>\u003cu>A2：\u003c/u>\u003cbr>我现在的工作从技术岗位转到了运营管理的岗位，也许大家也都经历过，拿到了一个新岗位，急需补充很多的原来不具备的知识和能力，觉得自己这也需要学习，那也不会，常常四处抓瞎。因为有了前面聚焦目标成功的经验，我选定学习项目管理的课程作为了近期的学习目标，目标的聚焦过程如下：\u003c/p>\u003cp>1、 研究生的学的是工商管理，其中包括有运营管理的课程。另外我们公司有一套成熟的管理体系来自于丰田管理体系，我之前也培训并使用过其中很多与项目相关的工具。所以目标与我已有的知识体系有一定的匹配度。\u003c/p>\u003cp>2、 我现在从售后的岗位转岗到了运营管理的岗位，其中也涉及小型的项目管理。项目管理的知识也是我现在急需补充的内容，如果这件事情现在不做我会因为没有尽力做好当下的事情而遗憾。\u003c/p>\u003cp>3、 现在每周两次线上项目管理课程，基本每天会刷题保持题感，11月27日参加PMP考试。在本年度我经手的每个项目也会刻意的应用1-2个项目管理中学到的工具或者方法。\u003c/p>\u003cp>以上就是我的三张便签。希望通过分享，小伙伴们能够理解了聚焦目标的方法。谢谢大家。有希望这个方法能够帮到在场的小伙伴们找到自己真正感兴趣的目标，制定的每个flag都不倒！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1685801469000,"updated_at":1686286607000,"ria":true},{"id":15853,"topic":"如何实施费曼学习法","learn_goal":"","remark":"费曼学习法分享，如何让知识用起来","level":"TF1-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"宁静@微光","city":"廊坊市"},"club":{"name":"廊坊风陵分舵","city":"廊坊"},"prologue":"\u003cp>各位好！我叫宁静。诸葛亮《诫子书》 中有两句至理名言：“非淡泊以明智，非宁静以致远” 。我愿在宁静中寻求安定，在安定中寻求智慧，在智慧中寻求快乐幸福的人生。 \u003c/p>\u003cp> 我给自己贴了三个标签：\u003c/p>\u003cp>幸福教育的探索者。解脱教育之困，感受教育之福。\u003c/p>\u003cp>致慧瑜伽的修炼者。链接高维空间，增长人生智慧。\u003c/p>\u003cp>超越自我的学习者。无极限地成长，有品质地生活。\u003c/p>\u003cp>\u003cstrong>【介绍拆书法、拆书帮】\u003c/strong>2分钟 \u003c/p>\u003cp> “拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习。这种学习法有三个特点：\u003c/p>\u003cp> 1、强调以学习者为中心而不是以知识为中心。\u003c/p>\u003cp>2、“拆书”分为个人学习的拆书法和组织学习的拆书法。个人学习的应用是RIA便签法。组织学习的应用是一位拆书家拿一本书，加工成一场现场学习，引领一群人把知识拆为己用。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部），拆书帮是非营利性青年自组织。据4月份统计，全球有56个正式分舵，18个筹备分舵。\u003c/p>\u003cp> 拆书帮使命：致力于培养拆书家，释放拆书家的能量，相互陪伴，助人达己。\u003c/p>\u003cp> 拆书帮愿景:帮助拆书家们升级学习力和促进他人学习力的能力，影响身边的人， 让世界变得更好一点。\u003c/p>\u003cp> 拆书帮价值观：即陪伴赋能、拆为己用、反求诸己、持续精进、共同成长。\u003c/p>\u003cp>个人感悟：拆书帮是一个开发和升级的平台。\u003c/p>\u003cp>开发思维，升级大脑；开发资源，升级人脉；开发潜能、升级价值。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>（1分钟），\u003c/p>\u003cp>作者：微博教育博主@写书哥，近百万粉丝。来自农村，未参加过任何培训班，也没依靠父母指导学业，凭借对费曼学习法的应用，一路从村小考入清华。初中三年，数学考试多数满分。“老师拿着放大镜都找不到扣分点”。他目前投身于出版行业，策划过多本畅销书，旨在让更多孩子轻松学习，高效收获，快乐成长。相信我们对这本书的拆解同样会收获宝贵的学习经验。下面请大家用2分钟时间阅读这个片段，看完请在评论区打1，提示我看完了。\u003c/p>","ratings_count":1,"texts":[{"id":19931,"quote":"\u003cp>\u003cstrong>如何实施费曼学习法【P13-14页】。\u003c/strong> \u003c/p>\u003cp> 严格来说，费曼学习法并不是一种方法，而是一种思维模式。这种思维模式会不自觉地影响行为模式。\u003c/p>\u003cp> 但如果直接把费曼学习法说成一种模式，难免有些难以理解，也难以落实。所以，我们在应用费曼学习法时，可以按照以下步骤进行。\u003c/p>\u003cp> 1.制定目标\u003c/p>\u003cp>学习之前，我们首先要制定一个明确的目标。制定学习目标应当遵循 SMART 原则，也就是目标应当是具体的(Specific)、可以衡量的(Measurable)、可以达到的(Attainable)、具备相关性的(Relevant)以及有明确截止期限的(Time-bound)。有了目标之后，我们还要制订具体的行动计划。\u003c/p>\u003cp> 2.尝试输出\u003c/p>\u003cp>感觉自己学会后，我们可以尝试输出学习内容，验证自己有没有学会。在课业学习方面，除了向别人分享外，我们还可以通过写作业、考试等方式来输出和验证学习成果。费曼十分喜欢用口语阐述的方式来写作，甚至在写严谨的科学论文的时候也是如此，他还喜欢利用图表来展示晦涩复杂的量子力学。\u003c/p>\u003cp> 3.发现问题\u003c/p>\u003cp> 有了第2步的输出后，我们就会发现自己没掌握知识的原因可能是多方面的，有可能是记忆问题，即自己没记住;有可能是理解问题，即自己没有真的理解知识;也可能是视野问题，即自己知识的边界没有打开。这时候我们可以有针对性地进行复习。\u003c/p>\u003cp> 4.真正掌握\u003c/p>\u003cp> 经过第3步后，我们对知识的理解将会更进一步，会发现哪些知识是最重要的。当然，这时候我们也不要自满，还需要再次验证自己有没有真正掌握。只有能融会贯通，才算真正掌握了知识。\u003c/p>","explains":"\u003cp>费曼学习法是目前世界公认的一种高效的学习方法，让知识融会贯通，也是一种科学的思维模式，让人终身受益。也是是世界公认的一种高效学习法，很多名人都推崇，如苹果公司创始人史蒂夫•乔布斯，微软公司创始人比尔盖茨等。\u003c/p>\u003cp>What :这个片段讲的是费曼学习法的四个步骤。\u003c/p>\u003cp>How:费曼学习四步法：\u003c/p>\u003cp> 1、制定目标。制定一个清晰的符合SMART原则的目标（具体、可衡量、可达到、具备相关性的、有明确截止期限的）\u003c/p>\u003cp> 2、尝试输出。例如分享、写作业、图表展示等等。\u003c/p>\u003cp> 3、发现问题。找出薄弱的地方有针对性地复习巩固。\u003c/p>\u003cp> 4、真正掌握。深入理解运用知识，融会贯通，成为一种能力。\u003c/p>\u003cp>Why：为什么要用费曼学习法呢？（1）促使主动学习（2）发现核心知识（3）让知识融会贯通。（4）避免低水平勤奋（5）更容易收获学习成果。\u003c/p>\u003cp>Why not: 我们传统的学习方法投入时间多，但收效甚微，容易丧失学习信心。\u003c/p>\u003cp>Where：读书、学习、工作都可以用费曼学习法，适合学习任何一项技能。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验】\u003c/strong>2分钟\u003c/p>\u003cp>两个月前我买了《语言赋能》这本书，当时并没有确定清晰的目标，只是看见这本书似乎很畅销，感觉对 提升语言的赋能有帮助，于是赶紧买来读，虽然这本书我读了两遍，但看完没有做笔记输出，也没有任何形式的分享。结果现在书中的东西我已然忘得差不多了，也没有实现我期待的目标。\u003c/p>\u003cp>反思：\u003c/p>\u003cp>读书一定要讲究方法，所谓方法正确努力才有意义，否则浪费时间和精力，劳而无功。\u003c/p>\u003cp>\u003cstrong>【A2具体应用】\u003c/strong>2分钟\u003c/p>\u003cp>五一以后，我决定用费曼学习法重读《语言赋能》这本书，并采取以下步骤：\u003c/p>\u003cp>1、制定目标。我的目标是5月30日之前看完这本书，然后从中找出两段拆页。\u003c/p>\u003cp>2、尝试输出。\u003c/p>\u003cp>（1）5月30之前组织一次群线上或者线下分享，将《语言赋能》中的相关知识分享给朋友。\u003c/p>\u003cp>（2）从今天（5月4日）开始，每天写每一篇读书笔记，坚持到5月30日。\u003c/p>\u003cp>3、发现问题：读书和分享的过程中多反思，对不理解、讲不透彻的地方重点学习探讨。\u003c/p>\u003cp>4、真正掌握：将费曼学习法运用到各类学习中，不仅仅是读书，包括我练习瑜伽，学习葫芦丝、参加各种培训等，最终让费曼学习法成为习惯。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>1分钟\u003c/p>\u003cp>今天我们的学习就到此结束，希望今天的内容对大家有所帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1684654576000,"updated_at":1684720317000,"ria":true},{"id":14462,"topic":"用费曼学习法复述知识","learn_goal":"","remark":"学习，不再是老师讲、学生听，或者我们自己单纯地看书，而是要“反客为主”，反复讲解和复述，就在不断复述的过程中，自己就能学得更好、更融会贯通。","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"支帆","city":"邢台市"},"club":{"name":"邢台筹备分舵","city":"邢台"},"prologue":"\u003cp>我先介绍一下自己，大家好，我是支帆，很高兴能和大家一起学习，我是终身学习者，梦想实践者，不惧艰辛，坚持不懈的人。可以看到咱们今天现场来了两位小伙伴，在这里就不再分组了，一会希望在场的小伙伴能够参与进来，讨论分享自己的经验。\u003c/p>","ratings_count":1,"texts":[{"id":18477,"quote":"\u003cp>第一次复述时，应该如何实施从开始到结束的整个过程？我们可以分成三个阶段：\u003c/p>\u003cp>第一个阶段：凭印象复述。\u003c/p>\u003cp>开始复述时，可以描绘一下那些你自己记得最清楚的内容，把印象深刻的部分讲述出来。比如特别的观点、有趣的案例和别出心裁的论证等。不用顾虑说得是否准确，要自由、大胆和随心所欲地讲出自己的印象。根据这些讲述出来的印象，回头可以去整理这些知识点，进行二次学习和比对。我有一个习惯，了解到一个知识时我先快速自己把它讲一遍，然后统计哪些讲得对，哪些偏离了原意，回头再根据这个统计重点学习。\u003c/p>\u003cp>第二个阶段：复述中提出问题。\u003c/p>\u003cp>第二个阶段并不是在几天之后，而是随后进行，也就是当你对自己讲完对知识的初步印象后。比如喝一杯茶，在5分钟、10分钟之后。这时我希望你的手上多了一张纸，上面记着你在第一个阶段复述时印象深刻的知识点。这个阶段的复述不仅仅是重温你刚刚学到的内容，而是有意识地将它们与自己过去已知道的知识相结合，进行对比，怀疑，分析，看能否用自己的逻辑很好地把它们融合到一起。如果不能，针对这些知识点提出新的问题，写下一系列的“为什么”。你要解决这些“为什么”，才能把知识变成你自己独有的智慧，并且成功地输出给别人。\u003c/p>\u003cp>第三个阶段：复述中加入自己的观点。\u003c/p>\u003cp>最后一个阶段是为了完成我们对于知识的理解和升华。通过对所学内容的复述，一边说一边对比检查，把自己的观点加进去，实现新知识与自身已有的知识系统的衔接。比如，我学习了如何维修汽车发动机，便和自己开车时总结的经验结合起来，为一些过去的疑问找到了答案，对汽车便有了更深的见解。当你在新知识的基础上形成了自己的观点，才能到各个分享平台传播你的见解，输出你的观点，从更大的群体中获得更广泛的反馈，加速自己的进步。\u003c/p>","explains":"\u003cp>好的学子方法，往往能够起到事半功倍的效果，这里和大家分享一个高级的学习方法，简单实用，容易实操，接下来介绍一下内容都是什么【复述】学习一遍之后，凭借印象复述一遍；\u003cbr>【提出问题】针对复述中，自己发现的，还是不是很清楚的地方，提出问题\u003cbr>【加入自己观点】在复述中融入自己观点\u003cbr>\u003cbr>\u003c/p>","interaction":"\u003cp>那么讲解之后，大家是否清楚和了解了呢，接下来，邀请小伙伴咱们现场实际运用一下怎么样？\u003cbr>现有清胡胡，我之前学了中医理论，并给用到了孩子身上，看了许多中医的理论知识，但是很多时候，感觉领悟的不是很融会贯通，我用复述这个方法，首先我看了一个片段，关于小儿中医的，然后我合上书，给老公复述一遍，复述过程中，发现有些细节的地方没有注意到，这是我的一个问题所在，所以我记下来，然后接着往下说，并在其中加了自己的观点，用自己的话，更能使知识和自己的理解结合到一起。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1667206121000,"updated_at":1726635424000,"ria":true},{"id":13436,"topic":"费曼学习法步骤","learn_goal":"","remark":"拆书主题：费曼学习法步骤\n书籍名称：《费曼学习法》\n个人介绍： 制造业项目经理， 健康生活倡导者，终身学习践行者 挑战等级：TF1-2\n拆书时长：15分钟\n学习者收获：看了很多书，学了很多知识，但是记不住，说不清。费曼学习法帮助大家提升内容留存率至90%以上。\n结缘拆书: 因读书进入社群而结缘拆书帮，因赵周老师《这样读书就够了》激发成为拆书家的愿望。\n","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"Joanna Liu","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cul>\u003cli>大家好，我是今天的拆书家Joanna，也可以叫我乔安，挑战等级1-2。欢迎大家见证我升级打怪，也希望今天拆书的片段大家有所收获。\u003cbr>\u003c/li>\u003cli>刚才自我介绍大家已经知道我的第一个标签，制造业项目经理。我第二个标签，健康生活倡导者，就是希望用自己的行为影响越来越多的人坚持运动，保持健康的生活方式，第三个标签终身学习践行者，让我们一起在拆书中共同学习成长。\u003cbr>\u003c/li>\u003cli>今天拆书的片段来自《费曼学习法》。费曼学习法是由著名的诺贝尔物理学家理查德.费曼提出的，他在多个领域都有卓越的成就，就是因为他有一套独特的学习方法，是目前世界公认的最高效的学习方法。现在就让我们来解开费曼学习法的神秘面纱。我现在将拆页分发给大家，大家花1分钟时间阅读完，阅读完的小伙伴举手示意一下。\u003cbr>\u003c/li>\u003c/ul>","ratings_count":2,"texts":[{"id":17454,"quote":"\u003cul>\u003cli>后来，越来越多的人便采用他的这种方法学习，最终形成了人们众所周知的“费曼学习法”。\u003cbr>\u003c/li>\u003cli>它的核心是——当你准备学习一门新知识时，必须站在传授者的立场，假设自己要向别人讲解这门知识。那么你一定要用最简洁、清晰和易于理解的语言表达出来，才能让行外的人也能听懂。费曼说：“最好是几岁的小孩也能明白你在说什么。”为此，他制定了一个简单易行的流程：\u003cbr>\u003c/li>\u003cli>第一，确立你要学习的目标。找到和列出自己想要了解的知识，可以是一本书，也可以是一门技术，甚至是你能想象到的任意领域和事物。\u003cbr>\u003c/li>\u003cli>第二，理解你要学习的对象。针对这个目标，准备好和筛选相关的资料，选择可靠和多个角度的信息来源，把这些内容系统化地归纳整理出来。\u003cbr>\u003c/li>\u003cli>第三，以教代学，用输出代替输入。模拟一个传授的场景，用自己的语言把这些知识讲给别人，用以检查自己是否已经掌握了这些知识。\u003cbr>\u003c/li>\u003cli>第四，进行回顾和反思。对其中遇到阻碍、模糊不清和有疑义的知识重新学习、回顾和反思。如有必要，可以重整旗鼓，进行再一次输出。\u003cbr>\u003c/li>\u003cli>第五，实现知识的简化和吸收。最后，通过针对性的简化和整合，实现这些知识的内化和有效的应用。\u003cbr>\u003c/li>\u003cli>通过这五个步骤，我们很容易便能获得最高的内容留存率，加强学习的效果，让自己顺利地达到学习和输出知识的目的。\u003cbr>\u003c/li>\u003c/ul>","explains":"\u003cul>\u003cli>好，大家都已经读完。\u003cbr>\u003c/li>\u003cli>WHAT\u003cbr>\u003c/li>\u003cul>\u003cli>这段文字总结了费曼学习法的核心，也就是以教代学，用最简单的话，让一个外行都能听懂。费曼为此总结了五步简易可行的流程。\u003cbr>\u003c/li>\u003c/ul>\u003cli>HOW\u003cbr>\u003c/li>\u003cul>\u003cli>第一步：确定主题：即确认学习方向和内容。可以根据工作和学习的方向，确定想要深入学习的内容，可以还未掌握的知识点，或者容易遗忘的知识点等\u003cbr>\u003c/li>\u003cli>第二步：理解内容：即深入学习，尽可能多的渠道了解理解要学习的知识点，并系统化地归纳整理出来\u003cbr>\u003c/li>\u003cli>第三步：模拟教学：即模拟一个教学场景，像一个老师要教会一个什么都不懂的学生那样，去练习讲述和解释这些知识点；\u003cbr>\u003c/li>\u003cli>第四步：反思回顾：在讲述的过程中遇到任何疑问时，再回过头去重新学习，反思和修正，直到完全理解为止\u003cbr>\u003c/li>\u003cli>第五步：简化吸收：提取知识点中的精华，将知识点尽可能简化，用自己通俗易懂的语言归纳整理，形成自己的知识体系和观点，达到知识转化和内化的目的。\u003cbr>\u003c/li>\u003c/ul>\u003c/ul>\u003cp>WHY\u003cbr>\u003c/p>\u003cul>\u003cul>\u003cli>我们说最高级的学习就是教会别人，当我们采用这种方法，将知识用自己的语言精炼地表达出来时，就能获得最高的内容留存率，达到学习和输出知识的目的。\u003cbr>\u003c/li>\u003c/ul>\u003c/ul>\u003cp>WHERE\u003cbr>\u003c/p>\u003cul>\u003cul>\u003cli>费曼学习法适用知识层面的学习，不适用于技能和能力层面的学习，就算把理论讲得再透彻，也可能学不会游泳，骑自行车，有纸上谈兵之嫌。\u003cbr>\u003c/li>\u003c/ul>\u003cli>举例说明\u003cbr>\u003c/li>\u003cul>\u003cli>举例来说，对于我每一次参加拆书帮活动就是一次实践费曼学习法的过程。首先第一步，我会根据自身学习目标选择拆页，比如本次过级我选择的书籍是刻费曼学习法；第二步，理解内容，我会阅读原文上下文，必要时查找其他更多关于这个片段的知识点，加深理解；第三步，模拟教学，我通过逐字稿的打磨来检验对知识点的掌握情况，然后发给教练进行修正，第四步，打磨过程中如果有不清楚的地方需要复习原文或查找资料，第五步最后简化语言整理成PPT，然后通俗地讲解展示给大家。\u003cbr>\u003c/li>\u003c/ul>\u003c/ul>","interaction":"\u003cul>\u003cli>A1激活学习者经验\u003cbr>\u003c/li>\u003cul>\u003cli>接下来我们会进行小组讨论分享，为了便于后面的讨论，我们先分个组，2人一组\u003cbr>\u003c/li>\u003cli>请大家想想自己亲身经历或者见过的运用了费曼学习法的案例，小组内分享，时间4分钟，然后我们会选一个小组进行分享，现在开始吧。\u003c/li>\u003c/ul>\u003c/ul>\u003cp>学习者案例记录：\u003c/p>\u003cp>Wendy分享到：\u003c/p>\u003cp>上周让孩子讲解新知，用自己的语言将知识点讲给父母听，检验孩子掌握知识的程度\u003c/p>\u003cp>A2催化学习者应用\u003cbr>\u003c/p>\u003cul>\u003cul>\u003cli>最后一分钟请大家规划未来如何应用费曼学习法，大家可以写下应用的关键词，包括应用场景，最好这个应用规划是有时间限制的，是可衡量的，是具体的\u003cbr>\u003c/li>\u003c/ul>\u003c/ul>\u003cp>学习者案例记录：\u003c/p>\u003cp>卷福分享到：\u003c/p>\u003cp>场景：拜访客户讲解方案\u003c/p>\u003cp>时间：下周五\u003c/p>\u003cp>目标：对于新概念可以理解透彻，用自己的话给客户讲清楚\u003c/p>\u003cp>对象：客户\u003c/p>\u003cp>模拟教学：与家人模拟讲解\u003c/p>\u003cul>\u003cli>以上是本次拆书的所有内容，请观察家停表。希望大家听有收获，也能真正学以致用。谢谢大家！\u003cbr>\u003c/li>\u003c/ul>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1653095520000,"updated_at":1653297180000,"ria":true},{"id":12239,"topic":"以教代学，通过简洁有深度的输","learn_goal":"","remark":"《费曼学习法》这本书中最核心的观点，就是用输出倒逼输入，当你准备学习一门知识时，必须站在传授者的立场，假设自己要向别人讲解这门知识。其中两大关键思维分别是简化思维——把高深的知识用平实的话语说出来才是学透；输出思维——不卡壳复述学习内容才是学全。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"abbylzw","city":""},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>大家好，我是拆书家李仲雯，你们也可以叫我Abby。首先，我用3个标签来介绍一下自己。\u003c/p>\u003cp>第一个标签是 组织发展。我是乙方咨询顾问出身，现在在一家生物医药公司负责组织发展和人才发展相关工作。\u003c/p>\u003cp>第二个标签是学习者。我是一个乐于学习新知识的人，目前也是在备考证书中。\u003c/p>\u003cp>第三个标签是新手拆书家，希望能逐步应用好RIA和引导的方法，未来成为一名学习促动者。\u003c/p>\u003cp>我今天分享的是《费曼学习法》。 费曼是一位物理学家，他一生有着足以铭刻史册的学术成就，同时，他也因自己独特的教学方式——也就是费曼学习法——广为人知，深受推崇。\u003c/p>\u003cp> 《费曼学习法》这本书中最核心的观点，就是用输出倒逼输入，当你准备学习一门知识时，必须站在传授者的立场，假设自己要向别人讲解这门知识。其中两大关键思维分别是简化思维——把高深的知识用平实的话语说出来才是学透；输出思维——不卡壳复述学习内容才是学全。\u003c/p>","ratings_count":1,"texts":[{"id":16150,"quote":"\u003cp>网上曾经有一门十分流行的课程，名字叫作《如何成为有效学习的高手》。主讲人向听众分享他在学习方面的经验时，讲到的第一个原则就是——学完一门知识，他就将它制作成课程，挂到互联网销售。这位主讲人的思路也是费曼学习法“以教代学”的方法，既是目标，还是一种倒逼式的学习策略。\u003c/p>\u003cp>试想一下，将你学到的知识制作成一个人们愿意付费购买的课程需要具备哪些条件呢？这就让学习不再是你一个人的事情，因为人们花钱买你的知识肯定不是随便看看的，是为了从你这里学到有用的东西；现代社会的生活和工作节奏越来越快，人们也不想在读书求知上花费太多的时间，所以你的课程必须简洁易懂，不能让人一边看一边查资料；同时，还要具有自己独特的分析，也就是知识的深度，学了以后能够解决实际的问题，这样人们才觉得钱花得值。那么，在输出知识时你就不能简单地复制粘贴，而是既能总结出知识的精华，又能加上自己深刻的理解，还要用大家都能看懂、听懂的语言往外传播。\u003c/p>\u003cp> 第一，语言简洁易懂。正如前面所说，你在阐述一门知识时能否让一位没文化的农民也能立刻听得懂？另外，能否做到用最少的话表达出最多的内涵？这很考验我们的语言组织和对精华知识的归纳能力。\u003c/p>\u003cp>第二，精准到位，没有歧义。要精准，就要用对词，既精练又犀利地把知识阐述清楚，要保证听者第一时间就能够领会到你的观点，而且跟知识的原义相符不会产生误解。当然可以有误差，但不能出现根本的偏差。\u003c/p>\u003cp>第三，讲出一定的深度。要有深入的分析和延伸，讲出知识的应用和比较重要的价值。不能仅是肤浅的阐述，否则以教代学就失去了应有的意义。大部分人很难做到这一点，是因为他们在学习时从来不思考，总是囫囵吞枣，以死板的记忆而不是以深入的思考和灵活的应用为目的。这样的学习在输出知识时便自然而然地缺乏深度，只能充当一个复读机的角色。\u003c/p>\u003cp>第四，加上自己的理解。在把知识教授给别人时适当加入自己的原创观点，或者举一反三，引入其他的知识作为比照，在对比中突出你所具备的知识的特点。这么做可以通过听者的反馈来验证自己的理解，有机会发现问题，回去再从进一步的学习中改善这些问题。\u003c/p>","explains":"\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>看完拆页片段，我相信大家都会回想起过去的经历和感受，用一个比较时髦的短语来说，就是“学会了，但又没有完全学会”。研究表明，当你在听别人讲或者自己阅读书籍的时候，内容留存率只有5%-10%，但是当你去把这个知识教授给他人的时候，内容留存率可以高达90%。“以教代学”是一种非常有效的学习方式。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>因为当我们对知识进行加工，并教授给他人的时候，我们对知识理解就会更深。但如果没有输出，只有输入，就容易消化不良，也就是“边学边忘”。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>那么怎么样能教得更好，从而对知识掌握更深更透彻呢？书中用了四个步骤，我也结合自己的经验分享一下，因为我之前经常给销售培训一些产品知识，包括财务、金融、咨询方法、经典案例等等都有，在我给销售培训的过程中，我自己对知识理解是更深刻的。\u003c/p>\u003cp>1.第一步，用简练的语言归纳。我以前给销售培训的时候，我一般都是避免用一些生涩难懂的词汇，例如在教销售同事财务专业知识的时候，我不会深入讲解会计准则，或者是复杂的分析模型，而是归纳出最核心的框架，提炼要点。\u003c/p>\u003cp>2.第二步，教授时要精准用词。对一些专有名词，和一些行业通用的说法，我会去精准阐述，例如成本和费用是有区别的，不能混为一谈。\u003c/p>\u003cp>3.第三步，要有深度的思考。给销售培训不能只是照着书中的内容去读，我之前的做法是我会画一个框架图，包括知识要点，公司一般是怎么做的，我们以前服务的案例是怎么做的。\u003c/p>\u003cp>4.加上自己的色彩。我在给销售培训的时候，我会加上我自己对客户需求的理解，目前客户可能有的痛点有哪些，给到销售更多的信息帮助售前打单。\u003c/p>\u003cp>通过这几个步骤，在教会了销售同事知识体系的过程中，我自己对财务知识了解不断深入，不久之后就设计并退出了很多培训、轻咨询产品。当然对于参加培训的销售来说，他们也掌握了新知识，提高了成单率至少20%，可谓是双赢。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>以教代学的方式可以应用在几乎所有的学习场景中，不仅仅是成人学习，其实小孩的学习也是一样的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验】\u003c/strong>\u003c/p>\u003cp>我们现在分一下组，分为两个小组。请大家在小组内分享一下，自己过去学习知识的经验，是否用过这种“以教代学”的方式，可以说自己成功的经验，例如自己有意识无意识地用了这种输出倒逼输入的方式，也可以说自己失败的经验，例如学习转化不高，学了就忘的情况等等。\u003c/p>\u003cp>请大家花3分钟讨论一下，我等下请一位小伙伴分享自己的经验\u003c/p>\u003cp>\u003cstrong>【A1现场分享】\u003c/strong>\u003c/p>\u003cp>王承诚分享：我是经常应用“以教代学”的方式，因为自己作为私人教练的培训师，需要教这些教练一些肌肉，运动方面的理论。如果只是看书，那些肌肉、骨骼，人体解剖学的内容是很难理解的，但是通过教他们，就掌握很深入。\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>拆书就是学以致用，所以最后一步就是请大家花一分钟在便利贴上写下自己未来要怎么用以教代学四步法去更好地学习知识。请大家写下来未来一段时间内，你准备做什么事情，具体的行动方案是什么。请写清楚时限（一周/一个月），可落地，可衡量。比如我在下周会和我的朋友分享什么是“RIA拆书法”，怎么衡量呢，就是通过下一次拆书现场对拆书法的介绍是否更精准了。请写完的伙伴把便利贴给到我。\u003c/p>\u003cp>\u003cstrong>【A2分享】\u003c/strong>\u003c/p>\u003cp>笑一：未来一周，我会看一本书，看完之后分享给小伙伴，首先用自己的简练的语言来表达，其次精准用词，把知识阐述清楚，然后把关键点延申灵活应用，最后用自己理解的语言去解读。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1630288788000,"updated_at":1630398834000,"ria":true},{"id":11411,"topic":"三步把学到的知识“可视化”","learn_goal":"","remark":"《费曼学习法》费曼学习法的核心，是把复杂的知识简单化，以教代学，让输出倒逼输入。这不只是一种学习方法，更是一种思维方式。学霸都在用！","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"李婧初","city":"北京市"},"club":{"name":"燕郊星火分舵","city":"廊坊"},"prologue":"\u003cp>【自我介绍】大家好，我是今天的拆书家婧初。\u003c/p>\u003cp>一样的惯例，向大家介绍一下我的三个标签是：5岁男孩的宝妈、视觉呈现爱好者、拆书路上的新人。\u003c/p>\u003cp>关注拆书已久，终于在这个春天开始了升级打怪之旅，我期望今年能够完成二级拆书家的认证。\u003c/p>\u003cp>正式拆书之前呢，想先来和大家聊聊这个让我惦念了好几年的“拆书帮”和它的独门武功秘籍“拆书法”\u003c/p>\u003cp>【介绍拆书法】拆书是一种学习方法论，这个拆字特别的形象，我们可以理解为利用这种方法，我们把一本书里的知识拆开揉碎，真正理解掌握、吸收内化。这种学习方法是基于学习者为中心，把知识联系到个人的经验，进而规划具体的应用，最终达到学以致用的目的。\u003c/p>\u003cp>拆书法的应用广泛，不仅可以个人学习，也可以组织一群人一起学习。\u003c/p>\u003cp>个人学习应用的是RIA便签法。R代表阅读原文片段，I表示提炼原文中的核心知识点并用自己的话总结出来；A表示激活自己以往的经验，并规划未来的行动。\u003c/p>\u003cp>组织学习应用则是由一位拆书家现场带领大家一起学习，这种学习效果不亚于参与了一场专业的主题培训。\u003c/p>\u003cp>【介绍拆书帮】什么是拆书帮呢？是基于拆书法的学习爱好者的公益性社群。目前拆书帮已经成立8年，在全国28个省份47座城市，建立了47家正式分舵，15家筹备分舵。\u003c/p>\u003cp>拆书帮给所有的拆书家一个充分展示自我的机会，也通过社群的形式将这种有效的学习方法传递给更多人。\u003c/p>\u003cp>【过渡语】好啦，现在开始正式的拆书环节。\u003c/p>\u003cp>今天我将要拆解的书是《费曼学习法》。费曼是一位诺贝尔物理奖获得者，被认为是爱因斯坦之后最睿智的理论物理学家，他这套独有的学习方法，让他备受推崇，被称为是学霸都在用的方法。\u003c/p>\u003cp>今天我带来的拆书片段取自《费曼学习法》的P67-P69。\u003cem>现在我把原文拆页发给大家，请大家用2分钟时间阅读，读完后请大家举手或者看向我并点头示意。\u003c/em>\u003c/p>","ratings_count":1,"texts":[{"id":15332,"quote":"\u003cp>【原文片段】\u003c/p>\u003cp>我们对外界环境的感知主要是通过不同的感官实现，眼睛是获取知识最主要 的一条通道。为知识画一张思维导图的最主要目的，就是扩大眼睛的作用，让知 识变得立体化，使它的整体结构通过眼睛传输到大脑，可以节省很多不必要的精力。\u003c/p>\u003cp>那么，为何人们在学习和工作中还会本能地排斥思维导图的形式呢?有人觉得 画一张图太过麻烦，要准备纸，准备笔、还要启动大脑进行深入思考，分析知识 的结构，标注知识的要点。这让他觉得有难度。问题是，学习从来都不是一件轻 松的事情。你不可能像喝咖啡一样随随便便就能掌握一本书，或者不费吹灰之力 就记住一门语言，并在与外国人的交流中自如地使用它。如果你不想认真对待， 这一目标是不可能实现的。\u003c/p>\u003cp>思维导图的第一个作用，是把我们的注意力指向实质与最关键的信息，加深 我们对于知识的印象。这不仅有利于把握本质，也有助于记忆。比如，你可以先 对自己要读的一本书画一张概念图，把主题、用途等要素图形化，突出这本书的 理论和观点；再画一结构图，掲示目录、大章以及概念之间的关系，把书的不同 板块分类，形成一个简明的层次结构，有利于针对性的阅读；还可以画一张因果 图，列出书中的观点的前因后果，论据与推理逻辑之间的关系，这能为你提供一 个独立思考的窗口。你可以站在自己的角度思考书中的观点是否经得起推敲，是 否还需要寻找更多的论据来支撑他的观点。这就让我们的学习拥有了一种富有广 度和深度的宏观视野。\u003c/p>","explains":"\u003cp>【过渡语】好的，我看大家已经都阅读完原文片段了。下面我想和大家分享一下我对这个片段的理解\u003c/p>\u003cp>【自己的理解复述原文中的核心知识点】\u003c/p>\u003cp>\u003cem>【WHY】\u003c/em>片段中提到：我们对外界的感知主要通过不同的感官实现的。感官是我们接受外部刺激的器官，眼、耳、鼻、舌、体分别给我们带来视觉、听觉、嗅觉、味觉、触觉等不同的感受，而大脑是这一切的中枢系统。当我们在接触一个新的事物的时候，调动越多的感官参与，对大脑的刺激就越强，同时就更有利于我们记忆和吸收。费曼曾经说过：视觉是最高效的感官通道，因为它承担了大脑80%的信息输入任务。\u003c/p>\u003cp>\u003cem>【WHAT】\u003c/em>学习恰恰是一个信息输入的过程，如果想更好的提高信息输入的有效性，我们就要想办法增强刺激。利用思维导图这个工具就可以实现。\u003c/p>\u003cp>思维导图近几年特别火，这个工具可以帮助我们进行归纳总结、整理思路，我在工作中经常会使用这个工具。我觉得思维导图最神奇之处就是可以把一个知识或一个任务，以一种\u003cstrong>结构性\u003c/strong>的方式呈现在纸上，所有的要点一目了然，帮助大脑进行发散，把文字无法呈现出来的隐性思维“可视化”，仿佛给了我们一个“直升机视角”帮助我们去全局思考和理解。\u003c/p>\u003cp>\u003cem>【HOW】\u003c/em>在座的各位都是拆书家，一定都是爱看书的伙伴。在原文片段中，作者向我们介绍了在一个看书时把知识“可视化”的方法。\u003c/p>\u003cp>这个方法一共有三步：我把它概括为九字真言：抓概念——建结构——找因果\u003c/p>\u003cp>\u003cem>首先，抓概念是指 \u003c/em>我们在看一本的书的时候，可以画一个能够凸显结论和观点的概念图；\u003c/p>\u003cp>\u003cem>其次，建结构是指 \u003c/em>可以把书中各章节的内容组合起来画一张结构图，来体现彼此之间的关联或者逻辑关系\u003c/p>\u003cp>\u003cem>最后，找因果是指 \u003c/em>我们可以把书中的论据以及推理逻辑整理出来，画一张因果图\u003c/p>\u003cp>相信通过以上三张图，相信这本书的精华之处已经跃然于纸上了。\u003c/p>\u003cp>\u003cem>【Where】\u003c/em>这个方法，适用于我们看一本书或者学习一个新的知识的时候，它的作用不仅可以帮助我们更好的理解和吸收，也可以让我们有了一个全新的视角来思考和推敲。让我们的学习不仅有深度而且有广度。\u003c/p>","interaction":"\u003cp>【激活自己以往的经历】\u003c/p>\u003cp>\u003cem>下面我给大家分享一下我的个人经验。\u003c/em>不知道大家是否还记得，在我的三个标签中，有一个标签是“视觉呈现爱好者”。在我以往的学习中，我喜欢通过视觉手绘、视觉卡片或者思维导图的方式把我看书的内容或者听课的内容进行整理。在整理的过程中，我常常能够发现一些我还没有理解透彻的部分，然后我会再翻书或者查阅资料进行补充。\u003c/p>\u003cp>虽然做一张图经常会耗费不少的时间，每当完成一个作品的时候，也是一次查漏补缺强化理解的过程。\u003c/p>\u003cp>给大家展示一下我上个月做的一张图，这个知识点取自《将培训转化为商业结果》中的第二个法则——设计完整的体验。属于一个小的片段。那么对应我做的这张图是一张因果图。\u003c/p>\u003cp>第一部分表现了在培训转化过程中，会有哪些因素影响培训结果，第二部分表现了站在“客户”（也就是学员）的角度，在不同的项目阶段我们能够采取的相关行动。\u003c/p>\u003cp>因为第一部分的诸多影响，才有了第二部分的行动建议。\u003c/p>\u003cp>有了这样一张图，不仅形象的让我记住了这个章节的内容，也帮助我更好的理解这内在的逻辑关系。\u003c/p>\u003cp>【具体的行动计划】\u003c/p>\u003cp>\u003cem>接下来，我将如何使用这个把知识可视化的方法呢？\u003c/em>\u003c/p>\u003cp>我计划在本月底，将《费曼学习法》这本书的核心内容做一次“可视化”的整理。具体怎么做呢，三个步骤——九字真言\u003c/p>\u003cp>\u003cstrong>\u003cem>第一步：抓概念。\u003c/em>\u003c/strong>我要用一张概念图帮助我强化对《费曼学习法》核心理念的理解\u003c/p>\u003cp>\u003cstrong>\u003cem>第二步，建结构。\u003c/em>\u003c/strong>我要用一张结构图梳理费曼学习法的完整闭环\u003c/p>\u003cp>\u003cstrong>\u003cem>第三步，找因果。\u003c/em>\u003c/strong>我要用因果图追本溯源，把《费曼学习法》真正学透。\u003c/p>\u003cp>完成后会在群里跟大家分享，也请大家期待这次“视觉盛宴”。\u003c/p>\u003cp>好的，关于我今天的拆书分享就正式结束啦，希望这个方法可以给大家带来启发，在未来看书或者学习某个新知的时候通过【抓概念——建结构——找因果】三个步骤帮助我们更好的学习和理解。\u003c/p>\u003cp>谢谢大家\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1618889987000,"updated_at":1619061334000,"ria":true}]};